L3_1.m_Talk_JPN = "あれは……副社長ってあんなにすごい実力者だったの？"
L3_1.m_Talk_ENG = "What...? Was the Vice President such an impressive warrior?"
L3_1.m_Talk_TWN = "哇……副總這麼能打喔？"
L3_1.m_Talk_THA = "หา...? รองประธานเป็นนักรบที่เก่งขนาดนั้นเลยเหรอ?"
L3_1.m_Talk_VTN = "Gì cơ...? Phó Chủ Tịch là một chiến binh ấn tượng như vậy sao?"
L3_1.m_Talk_SCN = "那是……副总是这么厉害的制裁者吗？"
L3_1.m_Talk_DEU = "Was ...? War die Vizepräsidentin eine so beeindruckende Kriegerin?"
L3_1.m_Talk_FRA = "Quoi... ? La vice-présidente a toujours été aussi classe ?"
L4_1 = {}
L4_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@4#Talk"
L4_1.m_CutScenProcessKey = 4
