L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "これは驚きましたね。"
L4_1.m_Talk_ENG = "I'm a bit shocked."
L4_1.m_Talk_TWN = "嚇死我啦！"
L4_1.m_Talk_THA = "ช็อกเลยนะเนี่ย"
L4_1.m_Talk_VTN = "Tôi hơi sốc một chút."
