L4_1.m_Talk_FRA = "Je suis un peu choqué."
L5_1 = {}
L5_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@5#Talk"
L5_1.m_CutScenProcessKey = 5
L5_1.m_CutScenID = 378
L5_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L5_1.m_Pos = "R"
L5_1.m_Talk_KOREA = "앞으로는 부사장님 앞에서 말조심을 좀 해야겠어요."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "これから副社長の前では口を慎むことにしましょう。"
L5_1.m_Talk_ENG = "From now on, I should watch my mouth when speaking in front of her."
L5_1.m_Talk_TWN = "以後在副總面前說話要放尊重一點。"
L5_1.m_Talk_THA = "ต่อไปจะพูดอะไรต่อหน้าเธอต้องระวังปากหน่อยแล้วล่ะ"
L5_1.m_Talk_VTN = "Từ bây giờ, tôi nên tém mồm tém miệng lại khi nói chuyện trước mặt cô ấy."
L5_1.m_Talk_SCN = "从现在开始，在副总面前说话是不是得小心点了……"
L5_1.m_Talk_DEU = "Von nun an muss ich im Beisein der Vizepräsidentin vorsichtiger sein, was ich sage."
L5_1.m_Talk_FRA = "À partir de maintenant, je ferais mieux de surveiller ma langue devant elle."
L6_1 = {}
L6_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@6#Talk"
L6_1.m_CutScenProcessKey = 6
L6_1.m_CutScenID = 378
