L6_1.m_Crash = 15
L6_1.m_Talk_KOREA = "하지만 저대로 혼자 싸우게 둬도 되는 거야?"
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "でも、あのまま一人で戦わせてもいいわけ？"
L6_1.m_Talk_ENG = "But is it really okay to let her fight by herself like this?"
L6_1.m_Talk_TWN = "但放副總自己一個人真的沒關係嗎？"
L6_1.m_Talk_THA = "แต่ปล่อยเธอไปสู้คนเดียวแบบนี้ไม่เป็นไรจริงๆ เหรอ?"
L6_1.m_Talk_VTN = "Nhưng để cô ấy tự mình chiến đấu như thế này có thực sự ổn không?"
L6_1.m_Talk_SCN = "但是没关系吗？我们留副总在这里面对所有的敌人？"
L6_1.m_Talk_DEU = "Aber ist es wirklich in Ordnung, sie alleine alleine zu kämpfen?"
L6_1.m_Talk_FRA = "Mais... on peut vraiment la laisser se battre seule comme ça ?"
