L11_1.m_Pos = "C"
L11_1.m_Talk_KOREA = "부사장님. 저도 같이 남는 게 좋지 않을까요?"
L11_1.m_fTalkTime = 0.03
L11_1.m_Talk_JPN = "副社長。私も一緒に残った方がいいんじゃないですか？"
L11_1.m_Talk_ENG = "Vice President, wouldn’t it be better if I also stay back with you?"
L11_1.m_Talk_TWN = "副總，我也一起留下好嗎？"
L11_1.m_Talk_THA = "รองประธาน ให้ผมอยู่ที่นี่ด้วยจะดีกว่ารึเปล่าครับ?"
L11_1.m_Talk_VTN = "Phó Chủ Tịch, chẳng phải sẽ tốt hơn nếu tôi cũng ở lại cùng cô sao?"
L11_1.m_Talk_SCN = "副总，还是让我也一起留下来吧？"
L11_1.m_Talk_DEU = "Vizepräsidentin, wäre es nicht besser, wenn ich auch bei dir bleiben würde?"
L11_1.m_Talk_FRA = "Vice-présidente, ne vaudrait-il pas mieux que je vous accompagne ?"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 378
L12_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L12_1.m_Pos = "C"
L12_1.m_Talk_KOREA = "부사장님만큼은 아니겠지만…… 저도 펜릴 소대의 일원이니까요."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "副社長には及びませんが……私もフェンリル小隊の隊員ですから。"
L12_1.m_Talk_ENG = "Although I may not be as skilled as you... I too am a member of Fenrir Squad."
L12_1.m_Talk_TWN = "雖然我不比副總……但我也是芬里爾小隊的一員。"
L12_1.m_Talk_THA = "ถึงผมอาจไม่เก่งเท่าคุณ... แต่ผมก็เป็นสมาชิกหน่วยเฟนเรียร์เหมือนกันนะครับ"
L12_1.m_Talk_VTN = "Mặc dù có thể tôi không giỏi bằng cô... Tôi cũng là một thành viên của Tiểu Đội Fenrir."
L12_1.m_Talk_SCN = "虽然没有您这么厉害……不过我也是芬里尔小队的一员。"
L12_1.m_Talk_DEU = "Obwohl ich vielleicht nicht so qualifiziert bin wie du ... auch ich bin ein Mitglied des Fenrir-Trupps."
L12_1.m_Talk_FRA = "Je ne suis peut-être pas aussi qualifié que vous, mais... je suis quand même un membre de l'escouade Fenrir."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 378
L13_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L13_1.m_Pos = "C"
L13_1.m_Talk_KOREA = "……아니요. 시윤 군. 여긴 저 혼자로도 충분합니다."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "……いいえ。シリュウさん。ここは私一人でも十分です。"
L13_1.m_Talk_ENG = "...No, Shiyoon. I will be sufficient."
L13_1.m_Talk_TWN = "……不，時雲，這邊我自己可以應付。"
L13_1.m_Talk_THA = "...ไม่ต้องค่ะ คุณชิยุน แค่ฉันก็พอแล้ว"
L13_1.m_Talk_VTN = "... Không, Shiyoon. Mình tôi là đủ rồi."
L13_1.m_Talk_SCN = "……不，时云。这里就交给我吧。"
L13_1.m_Talk_DEU = "... Nein, Shiyoon. Ich allein werde ausreichen."
L13_1.m_Talk_FRA = "... Non, Charles. Je m'en chargerai seule."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 378
L14_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L14_1.m_Pos = "C"
L14_1.m_Talk_KOREA = "그러니 가서 꼭 미나 양을 지켜주세요."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "ですから、行ってぜひミナさんを守ってください。"
L14_1.m_Talk_ENG = "Therefore, please protect Mina at all costs."
L14_1.m_Talk_TWN = "你一定要去保護米娜。"
L14_1.m_Talk_THA = "เพราะฉะนั้น ช่วยปกป้องคุณมีนาทุกวิถีทางนะคะ"
L14_1.m_Talk_VTN = "Vậy nên, hãy bảo vệ Mina bằng mọi giá."
L14_1.m_Talk_SCN = "所以请继续保护米娜。"
L14_1.m_Talk_DEU = "Bitte beschütze Mina um jeden Preis."
L14_1.m_Talk_FRA = "Vous, vous devez protéger Mina à tout prix."
L15_1 = {}
L15_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 378
L15_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L15_1.m_Pos = "C"
L15_1.m_Talk_KOREA = "스승님이 사라진 이상, 미나 양을 지킬 사람은 시윤 군뿐이니까요."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "師匠が消えた以上、ミナさんを守れる人はシリュウさんだけですから。"
L15_1.m_Talk_ENG = "With Master absent at the moment, you’re the only one who can protect Mina."
L15_1.m_Talk_TWN = "師父消失後，能夠保護米娜的人就只剩你而已。"
L15_1.m_Talk_THA = "การที่อาจารย์หายตัวไปแบบนี้ ก็มีแต่คุณเท่านั้นที่ปกป้องคุณมีนาได้ค่ะ"
L15_1.m_Talk_VTN = "Đang lúc Sếp vắng mặt thế này, cậu là người duy nhất có thể bảo vệ Mina."
L15_1.m_Talk_SCN = "既然老师不在，唯一能保护米娜的人就剩下时云你了。"
L15_1.m_Talk_DEU = "Da die Meisterin im Moment abwesend ist, bist du der Einzige, der Mina beschützen kann, Shiyoon."
L15_1.m_Talk_FRA = "Sans le Maître pour nous aider, tu es le seul à pouvoir le faire."
L16_1 = {}
L16_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 378
L16_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "JOOSHIYOON_FENRIR_NULL_NULL"
L16_1.m_Pos = "C"
L16_1.m_Talk_KOREA = "어째서죠? 부사장님은 미나 양을 그다지 맘에 들어 하지 않는 줄 알았는데요."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "どうしてですか？　副社長はミナさんをあまり気に入ってないと思っていましたが。"
L16_1.m_Talk_ENG = "Why do you care about her so much? I thought that you didn’t have a high opinion of Mina?"
L16_1.m_Talk_TWN = "為什麼？我還以為副總你不怎麼喜歡米娜？"
L16_1.m_Talk_THA = "ทำไมคุณถึงห่วงเธอนักล่ะครับ? ผมนึกว่าคุณไม่ได้ใส่ใจอะไรคุณมีนานักซะอีก?"
L16_1.m_Talk_VTN = "Tại sao cô lại quan tâm đến cô ấy nhiều như vậy? Tôi nghĩ cô không đánh giá cao Mina chứ?"
L16_1.m_Talk_SCN = "为什么？我以为副总不太喜欢米娜。"
L16_1.m_Talk_DEU = "Warum liegt sie dir so am Herzen, Vizepräsidentin? Ich dachte, du würdest Mina nicht sonderlich mögen."
L16_1.m_Talk_FRA = "Pourquoi est-ce que vous vous inquiétez autant pour elle ? Je croyais que vous ne la portiez pas dans votre cœur."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 378
L17_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_LAUGH"
L17_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L17_1.m_Pos = "C"
L17_1.m_Talk_KOREA = "물론 전 미나양을 그리 좋아하지는 않습니다."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "もちろん私はミナさんがあまり好きではありません。"
L17_1.m_Talk_ENG = "Of course, I’d be lying if I said that I did."
L17_1.m_Talk_TWN = "我是不怎麼喜歡米娜，"
L17_1.m_Talk_THA = "ถ้าจะบอกว่าใส่ใจมากก็คงโกหกค่ะ"
L17_1.m_Talk_VTN = "Tất nhiên, tôi sẽ nói dối nếu tôi nói thế."
L17_1.m_Talk_SCN = "我确实不太喜欢米娜。"
L17_1.m_Talk_DEU = "Natürlich würde ich lügen, wenn ich sagen würde, dass ich Mina mag."
L17_1.m_Talk_FRA = "C'est vrai, oui. Je mentirais si je disais que c'était le cas."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 378
L18_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L18_1.m_Pos = "C"
L18_1.m_Talk_KOREA = "하지만 그녀에게 빚이 있는 것도 사실이죠."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "ですが、彼女に借りがあることもまた事実です。"
L18_1.m_Talk_ENG = "However, I do have a debt that I must repay to her."
L18_1.m_Talk_TWN = "但她確實有債。"
L18_1.m_Talk_THA = "แต่ถึงยังไงฉันก็มีหนี้ที่ต้องชดใช้ให้เธอ"
L18_1.m_Talk_VTN = "Tuy nhiên, tôi nợ cô ấy, mà nợ thì phải trả."
L18_1.m_Talk_SCN = "但我欠她的人情也是事实。"
L18_1.m_Talk_DEU = "Ich stehe jedoch in ihrer Schuld."
L18_1.m_Talk_FRA = "Mais j'ai une dette envers elle. Une dette que je dois rembourser."
L19_1 = {}
