L19_1.m_Talk_ENG = "A... debt?"
L19_1.m_Talk_TWN = "有……債？"
L19_1.m_Talk_THA = "หนี้... เหรอครับ?"
L19_1.m_Talk_VTN = "Một ... món nợ?"
L19_1.m_Talk_SCN = "欠……她的人情？"
L19_1.m_Talk_DEU = "In ihrer Schuld?"
L19_1.m_Talk_FRA = "Une dette ?"
L20_1 = {}
