L20_1.m_Talk_KOREA = "……아주 오래 전의 이야기입니다."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "……だいぶ前のことです。"
L20_1.m_Talk_ENG = "...It’s an old story."
L20_1.m_Talk_TWN = "……這已經是很久以前的事，"
L20_1.m_Talk_THA = "...เรื่องมันนานมาแล้วน่ะค่ะ"
L20_1.m_Talk_VTN = "... Đó là một câu chuyện cũ."
L20_1.m_Talk_SCN = "……是一个很久以前的故事。"
L20_1.m_Talk_DEU = "... Es ist eine alte Geschichte."
L20_1.m_Talk_FRA = "... C'est une vieille histoire."
L21_1 = {}
L21_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@21#Talk"
L21_1.m_CutScenProcessKey = 21
L21_1.m_CutScenID = 378
