L21_1.m_Face = "UNIT_IDLE"
L21_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L21_1.m_Pos = "C"
L21_1.m_Talk_KOREA = "클리파 차원에 도달해서 클리포트 게임을 중지시키려면, 반드시 미나 양이 그 곳에 있어야 합니다. 그것이 룰이니까요."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "クリファ次元に到達してクリフォトゲームを中止させるには、必ずミナさんがそこにいなければなりません。それがルールですから。"
L21_1.m_Talk_ENG = "In order to reach the Qlipha Dimension and put an end to the Qliphoth Game, Mina must be there in person. That’s the rule."
L21_1.m_Talk_TWN = "抵達逆卡巴拉次元後，若想停止逆卡巴拉遊戲，米娜就必須在那個地方，這是規則。"
L21_1.m_Talk_THA = "การจะไปให้ถึงมิติคลิฟ่าแล้วยุติคลิฟอธเกม คุณมีนาต้องไปด้วยตัวเอง กฎเป็นแบบนั้นค่ะ"
L21_1.m_Talk_VTN = "Để đến được Không Gian Qlipha và kết thúc Trò Chơi Qliphoth, Mina phải tự mình tới được đó. Luật là vậy."
L21_1.m_Talk_SCN = "而且如果想到达逆卡巴拉次元停止神圣战役，米娜就必须在那里。因为这是规则。"
L21_1.m_Talk_DEU = "Um die Klippa-Dimension zu erreichen und dem Klippot-Handstreich ein Ende zu setzen, muss Mina persönlich anwesend sein. Das ist die Regel."
L21_1.m_Talk_FRA = "Pour atteindre la dimension Qlipha et mettre fin au Jeu de Qliphoth, Mina doit être avec nous. C'est la règle."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 378
L22_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L22_1.m_Pos = "C"
L22_1.m_Talk_KOREA = "그리고 만약 그 과정에서 미나양이 사망한다면……"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "そしてもしその途中、ミナさんが死亡すると……"
L22_1.m_Talk_ENG = "And if Mina happens to die along the way..."
L22_1.m_Talk_TWN = "米娜若是在過程中死亡……"
L22_1.m_Talk_THA = "และถ้าคุณมีนาตายไประหว่างทาง"
L22_1.m_Talk_VTN = "Và nếu Mina chết trong quá trình đó..."
L22_1.m_Talk_SCN = "如果米娜在这个过程中死去……"
L22_1.m_Talk_DEU = "Und wenn Mina auf dem Weg sterben sollte ..."
L22_1.m_Talk_FRA = "Si nous n'arrivons pas à la garder en vie..."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP9_ACT4_STAGE4_END@23#Talk"
L24_1 = 23
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 378
L23_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L23_1.m_Pos = "C"
L24_1 = "그 순간 클리포트 게임은 우리의 패배로 끝나게 됩니다."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "その瞬間、クリフォトゲームは私たちの負けとなります。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Then the Qliphoth Game will end in our defeat."
L23_1.m_Talk_ENG = L24_1
L24_1 = "那逆卡巴拉遊戲就會瞬間以我們失敗作收。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "คลิฟอธเกมก็จะจบลงด้วยความพ่ายแพ้ของเรา"
L23_1.m_Talk_THA = L24_1
L24_1 = "Vậy thì chúng ta sẽ thua trong Trò Chơi Qliphoth."
L23_1.m_Talk_VTN = L24_1
L24_1 = "在那一刻，神圣战役将以我们的失败告终。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Dann endet der Klippot-Handstreich für uns mit einer Niederlage."
L23_1.m_Talk_DEU = L24_1
L24_1 = "... cela signera notre défaite."
L23_1.m_Talk_FRA = L24_1
