L26_1 = "EP9_ACT4_STAGE4_END@25#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 25
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 378
L25_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "이 게임과, 모든 마왕들과, 운명과 숙명을 감싼 실들은 미나 양을 중심으로 휘감겨 있습니다."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "このゲームと、すべての魔王と、運命と宿命を巡る糸はミナさんを中心に絡まっています。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "This game, all of the Demon Lords, the threads of Fate and Destiny, all of these are intertwined together with Mina at the center."
L25_1.m_Talk_ENG = L26_1
L26_1 = "將這個遊戲、所有魔王，以及命運和宿命纏在一起的線，都圍繞著米娜。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "เกมนี้ เจ้าแห่งดีม่อนทุกตน เส้นด้ายแห่งโชคชะตาและพรหมลิขิต ทั้งหมดล้วนถักทอเข้าด้วยกันโดยมีคุณมีนาอยู่ตรงศูนย์กลางค่ะ"
L25_1.m_Talk_THA = L26_1
L26_1 = "Trò chơi này, tất cả các Chúa Quỷ, các sợi dây của Định Mệnh và Số Phận, tất cả những thứ này đều hòa quyện vào nhau và Mina là trung tâm của những thứ đó."
L25_1.m_Talk_VTN = L26_1
L26_1 = "这场战役还有所有的魔王，命运和宿命纠缠不清的恩怨，都是以米娜为中心的。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Dieses Spiel, all die Dämonenfürsten, die Fäden von Schicksal und Bestimmung, alle sind mit Mina im Zentrum miteinander verflochten."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Le Jeu de Qliphoth, les Seigneurs démons, les fils du sort et du destin... Tout cela est lié, et Mina y joue un rôle central."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP9_ACT4_STAGE4_END@26#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 26
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 378
L26_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "저도 모든 것을 아는 것은 아니지만 미나 양은 마지막까지 살아남아야 합니다."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "私もすべてを知っているわけではないですが、ミナさんは最後まで生き残らなければなりません。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "I don’t know everything, but I can say with absolute certainty that Mina must survive until the end."
L26_1.m_Talk_ENG = L27_1
L27_1 = "我知道的也不是全部，但我只知道米娜必須存活到最後。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ฉันก็ไม่ได้รู้ทั้งหมดหรอกนะคะ แต่บอกได้อย่างแน่นอนเป็นที่สุดว่าคุณมีนาต้องมีชีวิตรอดไปจนจบค่ะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Tôi không biết toàn bộ câu chuyện, nhưng tôi có thể chắc chắn một điều rằng Mina phải sống sót cho đến cuối cùng."
L26_1.m_Talk_VTN = L27_1
L27_1 = "我也不知道全部情况，但米娜必须活到最后。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Ich weiß zwar nicht alles, aber ich kann mit absoluter Sicherheit sagen, dass Mina bis zum Ende überleben muss."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Je ne comprends pas tout moi-même, mais je suis sûre d'une chose : Mina doit survivre jusqu'au bout."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP9_ACT4_STAGE4_END@27#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 27
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 378
L27_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "그러지 못했기에…… 구 관리국은 결국 패망할 수밖에 없었습니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "それに失敗したから……旧管理局は結局敗亡したのです。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "That is why... The Old Administration fell in the end."
L27_1.m_Talk_ENG = L28_1
L28_1 = "舊管理局就是因為沒有做到……才會失敗的。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "และนั่นคือเหตุผล... ที่องค์การบริหารโลกในอดีตล้มเหลวในตอนท้าย"
L27_1.m_Talk_THA = L28_1
L28_1 = "Đó là lý do tại sao... đến phút chót, Cục Quản Lý Cũ thất bại."
L27_1.m_Talk_VTN = L28_1
L28_1 = "就因为旧管理局未能达成条件……最终才会失败。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Weil ich dies nicht verhindern konnte ... ist die Alte Administration schließlich zum Untergang verurteilt gewesen."
L27_1.m_Talk_DEU = L28_1
L28_1 = "C'est parce que cet objectif n'a pas été respecté... que l'Ancienne Administration a échoué."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
