L30_1 = "EP9_ACT4_STAGE4_END@29#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 29
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 378
L29_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L29_1.m_Pos = "C"
L30_1 = "그러니까 내 걱정은 말고, 뒤를 부탁합니다. 시윤 군."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "ですから私のことは気にせず、後を頼みます。シリュウさん。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Therefore, do not worry about me. I will leave the rest in your hands, Shiyoon."
L29_1.m_Talk_ENG = L30_1
L30_1 = "所以你不用擔心我，後面就交給你囉，時雲！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ดังนั้น ไม่ต้องห่วงฉันกันนะคะ ฝากที่เหลือด้วยค่ะคุณชิยุน"
L29_1.m_Talk_THA = L30_1
L30_1 = "Do đó, đừng lo cho tôi nữa. Mọi chuyện còn lại xin nhờ cậu, Shiyoon ạ."
L29_1.m_Talk_VTN = L30_1
L30_1 = "所以，别担心我。请你照顾好她，时云。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Mach dir daher keine Sorgen um mich. Ich werde dir den Rest überlassen, Shiyoon."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Quoi qu'il en soit, ne vous inquiétez pas pour moi. Je vous charge du reste, Charles."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L30_1.m_CutScenProcessKey = 30
