L31_1.m_Pos = "C"
L32_1 = "아뇨. 부사장님은 꼭 살아남으실 겁니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "いいえ。副社長は必ず生き残ります。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "No, she will survive."
L31_1.m_Talk_ENG = L32_1
L32_1 = "不，副總一定會活下來的。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ไม่ครับ รองประธานจะต้องรอด"
L31_1.m_Talk_THA = L32_1
L32_1 = "Không, Phó Chủ Tịch sẽ sống sót thôi"
L31_1.m_Talk_VTN = L32_1
L32_1 = "嗯，我相信副总一定可以活下来。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Nein, sie wird überleben, Vizepräsidentin."
L31_1.m_Talk_DEU = L32_1
L32_1 = "On doit lui faire confiance, elle survivra."
L31_1.m_Talk_FRA = L32_1
