L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "그러니 우린 우리의 일을 하도록 하죠."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "ですから僕たちは僕たちの仕事をやりましょう。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Therefore, we should focus on our mission."
L33_1.m_Talk_ENG = L34_1
L34_1 = "我們就做我們該做的吧！"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เพราะฉะนั้น เราก็จะสนใจแต่ภารกิจของตัวเองครับ"
L33_1.m_Talk_THA = L34_1
L34_1 = "Vì vậy, chúng ta nên tập trung vào nhiệm vụ của mình."
L33_1.m_Talk_VTN = L34_1
L34_1 = "所以我们要做好自己该做的事情。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Daher sollten wir uns auf unsere Mission konzentrieren."
L33_1.m_Talk_DEU = L34_1
L34_1 = "De notre côté, nous devons nous concentrer sur notre mission."
L33_1.m_Talk_FRA = L34_1
