L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "그게 부사장님이 바라는 것일 테니까요."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "それが副社長が望むことでしょうから。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "That is what she would expect from us."
L34_1.m_Talk_ENG = L35_1
L35_1 = "副總也是這麼希望的。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "เพราะนั่นคือสิ่งที่รองประธานคาดหวังจากเรา"
L34_1.m_Talk_THA = L35_1
L35_1 = "Đó là điều mà Phó Chủ Tịch mong muốn ở chúng ta."
L34_1.m_Talk_VTN = L35_1
L35_1 = "因为这也是副总所期望的。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Das würde die Vizepräsidentin von uns erwarten."
L34_1.m_Talk_DEU = L35_1
L35_1 = "C'est ce qu'elle attend de nous."
L34_1.m_Talk_FRA = L35_1
