L39_1 = "m_bCharHologramEffect"
L38_1[L39_1] = true
L39_1 = "신성반응 관측! 허신과 유사한 패턴의 침식파야!"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "神聖反応を観測！　虚神と酷似してるパターンの侵食波だよ！"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Divinity response detected! It’s a Corruption ray with a similar pattern to the Hollow God!"
L38_1.m_Talk_ENG = L39_1
L39_1 = "觀測到神聖反應！是類似幻神的侵蝕波！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "ตรวจพบการตอบสนองระดับเทวะ! เป็นรังสีคอร์รัปชั่นที่มีรูปแบบคล้ายเทพจอมปลอม!"
L38_1.m_Talk_THA = L39_1
L39_1 = "Đã phát hiện phản hồi cấp thánh! Đó là một Tia Ăn Mòn có hình thức giống giả thần!"
L38_1.m_Talk_VTN = L39_1
L39_1 = "侦测到神圣反应！是类似于虚神的侵蚀波类型！"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Erhabenheitsreaktion erkannt! Es sind Verderbniswellen mit einem ähnlichen Muster wie die eines Hohlen Gottes!"
L38_1.m_Talk_DEU = L39_1
L39_1 = "Réponse de divinité détectée ! Un Rayon de Corruption semblable à celui du Dieu illusoire est en approche !"
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP9_ACT4_STAGE4_END@39#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 39
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 378
L39_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L40_1 = "SYLVIA_DELTA_NULL_NULL"
L39_1.m_CharStrID = L40_1
L39_1.m_Pos = "R"
L40_1 = "부사장 아줌마 말대로야! 기사단 너머로 클리파 차원과 연결되는 포탈이 있었어!"
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "副社長のおばさんの言ったとおりだ！　騎士団の向こうにクリファ次元と繋がるポータルがあったんだ！"
L39_1.m_Talk_JPN = L40_1
L40_1 = "It’s just like the Vice President said! There’s a portal connected to the Qlipha Dimension behind the knights!"
L39_1.m_Talk_ENG = L40_1
L40_1 = "副總大嬸說的沒錯！騎士團那邊有連接逆卡巴拉次元的傳送門！"
L39_1.m_Talk_TWN = L40_1
L40_1 = "เหมือนที่ยายป้ารองประธานบอกเลย! มีประตูมิติที่เชื่อมกับมิติคลิฟ่าอยู่หลังพวกอัศวินจริงๆ ด้วย!"
L39_1.m_Talk_THA = L40_1
L40_1 = "Đúng như bà cô Phó Chủ Tịch đã nói! Có một cánh cổng kết nối với Không Gian Qlipha đằng sau các hiệp sĩ!"
L39_1.m_Talk_VTN = L40_1
L40_1 = "就像副总阿姨说的那样！突破骑士团后，真的有通往逆卡巴拉次元的传送门！"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Es ist genau wie die Vizepräsidentin gesagt hat! Es gibt ein Portal, das mit der Klippa-Dimension hinter den Rittern verbunden ist!"
L39_1.m_Talk_DEU = L40_1
L40_1 = "C'est exactement comme la vice-présidente l'avait dit ! Il y a un portail connecté à la dimension Qlipha derrière les Chevaliers !"
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP9_ACT4_STAGE4_END@40#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 40
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 378
L40_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L41_1 = "KYLE_DELTA_NULL_NULL"
L40_1.m_CharStrID = L41_1
L40_1.m_Pos = "L"
L41_1 = "확실히, 진군 자체에는 편법을 쓸 수 없어도 이미 진군한 거리만큼은 보급을 위한 지름길이 준비되어 있었군요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "確かに、進軍自体では抜け道を使えなくても、すでに進軍した分だけ補給のための近道が準備されていたんですね。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "Although no expedients were permitted for their advancement, it appears that they had planned shortcuts for the distances that they had already traveled."
L40_1.m_Talk_ENG = L41_1
L41_1 = "確實是，雖然進軍不能貪方便，但還是有準備好補給的捷徑。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ถึงจะห้ามใช้วิธีพิเศษในการบุก แต่กลายเป็นว่าพวกเขาจะ\nเตรียมทางลัดสำหรับเส้นทางที่ตัวเองเคยเดินทางไปแล้วเอาไว้นะครับ"
L40_1.m_Talk_THA = L41_1
L41_1 = "Mặc dù không có người thám hiểm nào từng đến, nhưng có vẻ như họ đã biết những lối tắt để rút ngắn khoảng cách trên những con đường mà họ đã đi."
L40_1.m_Talk_VTN = L41_1
L41_1 = "没错，虽然在神圣战役中，无法利用传送门作为行军的的捷径。不过他们可以以此进行补给。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Obwohl für ihre Weiterentwicklung keine Hilfsmittel erlaubt waren, scheint es, dass sie Abkürzungen für die bereits zurückgelegten Entfernungen geplant hatten."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Les règles du Jeu défendent peut-être l'utilisation de téléportation ou de raccourcis, mais il faut croire qu'une exception s'applique pour les chemins qui ont déjà été parcourus."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP9_ACT4_STAGE4_END@41#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 41
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 378
L41_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L42_1 = "KYLE_DELTA_NULL_NULL"
L41_1.m_CharStrID = L42_1
L41_1.m_Pos = "L"
L42_1 = "하지만 저 포탈은 신성 에너지로 보호되고 있습니다."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "ですが、あのポータルは神聖エネルギーによって保護されています。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "However, that portal is protected by Divinity energy."
L41_1.m_Talk_ENG = L42_1
L42_1 = "不過傳送門受到神聖能量保護，"
L41_1.m_Talk_TWN = L42_1
L42_1 = "แต่ยังไงก็ตาม มีพลังงานเทวะปกป้องประตูมิติอยู่"
L41_1.m_Talk_THA = L42_1
L42_1 = "Tuy nhiên, cánh cổng đó được bảo vệ bằng năng lượng Cấp Thánh."
L41_1.m_Talk_VTN = L42_1
L42_1 = "但是那个传送门受到神圣能量的保护。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Aber dieses Portal wird durch göttliche Energie geschützt."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Mais, ce portail... il est protégé par une énergie divine."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "EP9_ACT4_STAGE4_END@42#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 42
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 378
L42_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L42_1.m_bWaitClick = true
L42_1.m_fWaitTime = 0
L43_1 = "KYLE_DELTA_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "L"
L43_1 = "단기간에 저걸 파괴하고 안으로 들어가려면……"
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "短期間にあれを破壊して中へ入るためには……"
L42_1.m_Talk_JPN = L43_1
L43_1 = "If we’re to destroy that and enter within a short amount of time..."
L42_1.m_Talk_ENG = L43_1
L43_1 = "若要在短時間內破壞它進到裡面去的話……"
L42_1.m_Talk_TWN = L43_1
L43_1 = "ถ้าเราทำลายมันแล้วรีบเข้าไปให้ได้ละก็..."
L42_1.m_Talk_THA = L43_1
L43_1 = "Nếu chúng ta phá hủy nó và xâm nhập trong một khoảng thời gian ngắn ..."
L42_1.m_Talk_VTN = L43_1
L43_1 = "如果想在短时间内摧毁并进入……"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Wenn wir es zerstören und es innerhalb kurzer Zeit betreten ..."
L42_1.m_Talk_DEU = L43_1
L43_1 = "Si nous voulons le détruire et nous y engouffrer dans la foulée..."
L42_1.m_Talk_FRA = L43_1
