L46_1.m_Pos = "L"
L47_1 = "알고 있어. 울브즈베인이 필요하겠지."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "わかってる。ウルブズベインが必要なんでしょ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "I know. We need Wolvesbane."
L46_1.m_Talk_ENG = L47_1
L47_1 = "我知道，需要狼之災禍對吧！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "ฉันรู้ เราต้องใช้ดาบพิฆาตหมาป่า"
L46_1.m_Talk_THA = L47_1
L47_1 = "Tôi biết. Chúng ta cần Wolvesbane."
L46_1.m_Talk_VTN = L47_1
L47_1 = "我知道。需要使用狼之灾祸。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Ich weiß. Wir brauchen Wolfsbann."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Oui. Je vais utiliser la Plaie des loups."
L46_1.m_Talk_FRA = L47_1
