L48_1 = 25
L47_1.m_Crash = L48_1
L48_1 = "내가 나가서 길을 열겠어! 갑판으로 나가는 통로를 열어줘!"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "私が出て道を開ける！　デッキへの通路を開けて！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "I’ll go out and punch a path through! Open a route to the deck for me!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "我來開路！打開通往甲板的通道吧！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ฉันจะออกไปทะลวงทางให้เอง! เปิดเส้นทางสู่ดาดฟ้าให้ฉันด้วย!"
L47_1.m_Talk_THA = L48_1
L48_1 = "Tôi sẽ ra ngoài và đục một con đường xuyên qua! Mở đường đến boong tàu cho tôi!"
L47_1.m_Talk_VTN = L48_1
L48_1 = "我去开路！帮我打开通往甲板的通道！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Ich gehe hinaus und mache den Weg frei! Öffne den Durchgang zum Deck!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Je m'occupe de créer une ouverture ! Préparez-moi un passage sur la passerelle !"
L47_1.m_Talk_FRA = L48_1
