L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L5_1.m_Pos = "C"
L6_1 = "부사장님…… 죽으면 가만두지 않을 거야."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "副社長……死んだら承知しないからね。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Vice President... I’m not gonna forgive you if you die."
L5_1.m_Talk_ENG = L6_1
L6_1 = "副總……我可不准你死！"
L5_1.m_Talk_TWN = L6_1
L6_1 = "รองประธาน... ถ้าคุณตายไปฉันจะไม่ยกโทษให้นะคะ"
L5_1.m_Talk_THA = L6_1
L6_1 = "Phó chủ tịch ... Tôi sẽ không tha thứ nếu cô chết đâu."
L5_1.m_Talk_VTN = L6_1
L6_1 = "副总这个大妈……如果你死了，我是不会放过你的。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Vizepräsidentin ... Ich werde dir nicht vergeben, wenn du stirbst."
L5_1.m_Talk_DEU = L6_1
L6_1 = "Vice-présidente ... Si tu meurs ici, je ne te le pardonnerai pas."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP9_ACT4_STAGE4_END@56#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 56
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 378
L6_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L6_1.m_Pos = "C"
L7_1 = "잔소리를 해도, 감봉을 해도 좋으니까, 꼭 살아 있어야 해. 우리가 돌아올 때까지."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "小言を言っても、減俸してもいいから、絶対生きててよ。私たちが戻ってくるまで。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "You can scold me and deduct my pay. But please stay alive until we return."
L6_1.m_Talk_ENG = L7_1
L7_1 = "不管你要唸我，或是扣我薪水都好，總之在我們回來之前，你千萬不能死！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "จะด่ากันจะหักเงินแค่ไหนก็ได้ แต่ช่วยมีชีวิตอยู่จนเรากลับมาทีเถอะ"
L6_1.m_Talk_THA = L7_1
L7_1 = "Cô có thể mắng tôi và trừ lương của tôi. Nhưng hãy sống sót cho đến khi chúng tôi trở về."
L6_1.m_Talk_VTN = L7_1
L7_1 = "以后不管你唠叨多少遍要扣我工资，我都不会有一句怨言。所以直到我们回来的那一刻，一定要活下来啊！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Du kannst mich ausschimpfen und meinen Lohn kürzen. Aber bitte bleib am Leben, bis wir zurückkehren."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Tu peux m'engueuler, réduire mon salaire autant que tu veux... mais s'il te plaît, reste en vie jusqu'à notre retour."
L6_1.m_Talk_FRA = L7_1
