L28_1 = "能量源？从哪里来的？！"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Eine Energiequelle? Von wo kommt die denn so plötzlich?!"
L27_1.m_Talk_DEU = L28_1
L28_1 = "Une boule d'énergie ? D'où est-ce qu'elle vient ?"
L27_1.m_Talk_FRA = L28_1
