L29_1 = "UNIT_PRIDE"
L28_1.m_Face = L29_1
L29_1 = "FX_CUTSCEN_NOISE"
L28_1.m_StartFXSoundName = L29_1
L29_1 = "PRINCE_KNIGHT_NULL_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "m_bCharHologramEffect"
L28_1[L29_1] = true
L29_1 = "잠깐의 즐거운 희망은 잘 누렸느냐? 이방인들이여."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "しばしの楽しい希望は堪能できたか？　異邦人たちよ。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Did you enjoy your brief moment of hope, outsiders?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "外邦人，有享受到暫時的歡樂嗎？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "ได้มีความสุขกับความหวังที่ปรากฏขึ้นสั้นๆ หรือยัง คนนอกทั้งหลาย?"
L28_1.m_Talk_THA = L29_1
L29_1 = "Cô thích những khoảnh khắc hy vọng ngắn ngủi đó chứ, kẻ ngoại lai?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "有享受到暂时的希望吗，异乡人？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Habt ihr euren kurzen Moment der Hoffnung genossen, ihr Fremden?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "J'espère que vous avez bien savouré votre bref moment d'espoir, étrangers."
L28_1.m_Talk_FRA = L29_1
