L29_1.m_Pos = "C"
L29_1.m_Crash = 20
L30_1 = "너는……? 어떻게 여기에 있는 거지!"
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "君は……？　どうしてここにいる！"
L29_1.m_Talk_JPN = L30_1
L30_1 = "You...? How are you here?!"
L29_1.m_Talk_ENG = L30_1
L30_1 = "你……？怎麼會在這裡！"
L29_1.m_Talk_TWN = L30_1
L30_1 = "แก...? ทำไมมาอยู่ที่นี่ได้?!"
L29_1.m_Talk_THA = L30_1
L30_1 = "Ngươi...? Sao ngươi tới đây được?!"
L29_1.m_Talk_VTN = L30_1
L30_1 = "你……？你为什么会在这！"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Du ...? Wie bist du hierher gekommen?!"
L29_1.m_Talk_DEU = L30_1
L30_1 = "Toi...? Comment es-tu arrivé ici ?"
