L31_1 = "EP9_ACT4_STAGE4_END@80#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 80
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 378
L30_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L31_1 = "MARIA_DELTA_NULL_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "분명 코핀 컴퍼니의 부사장과 싸우고 있었을 텐데?"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "コフィンカンパニーの副社長と戦っていたはずだが？"
L30_1.m_Talk_JPN = L31_1
L31_1 = "You were definitely fighting against the Vice President of Coffin Company!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "你現在不是應該和科芬公司的副總打得不可開交嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "แกกำลังสู้อยู่กับรองประธานบริษัทคอฟฟินนี่!"
L30_1.m_Talk_THA = L31_1
L31_1 = "Chắc chắn ngươi đang chiến đấu với Phó Chủ Tịch của Công Ty Coffin mà!"
L30_1.m_Talk_VTN = L31_1
L31_1 = "不是应该正在和科芬公司的副总战斗吗？"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Du hast definitiv gegen die Vizepräsidentin der Coffin Company gekämpft!"
L30_1.m_Talk_DEU = L31_1
L31_1 = "Tu n'étais pas en train de combattre la vice-présidente de la Compagnie Coffin ?"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP9_ACT4_STAGE4_END@81#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 81
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 378
L31_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L32_1 = "UNIT_PRIDE"
L31_1.m_Face = L32_1
L32_1 = "PRINCE_KNIGHT_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "m_bCharHologramEffect"
L31_1[L32_1] = true
L32_1 = "흠, 그런 기만이야말로 우리 기사단의 성녀 루크레시아의 특기라고 할 수 있지."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "ふむ、そのような欺瞞こそ、我々騎士団の聖女ルクレシアの特技とも言えるだろう。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "That type of deception is the specialty of our Order’s Saintess, Lucrecia."
L31_1.m_Talk_ENG = L32_1
L32_1 = "哼，那種騙人的把戲，正是我們騎士團的聖女 露可蕾西亞最擅長的。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "การหลอกกันแบบนี้คือความเชี่ยวชาญเป็นพิเศษของนักบุญแห่งภาคีของเรานะ ลูเครเซียไงล่ะ"
L31_1.m_Talk_THA = L32_1
L32_1 = "Kiểu ảo ảnh đó là khả năng đặc biệt của Thánh Nữ của Hội của chúng ta, Lucrecia."
L31_1.m_Talk_VTN = L32_1
L32_1 = "哼，那种欺骗手段正是我们骑士团圣女卢克雷西亚的特长。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Diese Art der Täuschung ist die Spezialität der Heiligen unseres Ritterordens, Lucrecia."
L31_1.m_Talk_DEU = L32_1
L32_1 = "C'était sans compter les subterfuges dont seule notre Sainte à le secret."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP9_ACT4_STAGE4_END@82#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 82
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 378
L32_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "PRINCE_KNIGHT_NULL_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "C"
L33_1 = "그녀의 사령술로 나의 힘을 일부 나누어 만든 미끼라고 해야 할까?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "彼女の死霊術を使い、私の力を一部分けて作り上げたエサだと言っておこう。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "I guess you can say that it was bait created through her necromancy using a part of my power."
L32_1.m_Talk_ENG = L33_1
L33_1 = "應該說是她用死靈術分割出我部分的能力後完成的誘餌嗎？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "พวกเจ้าน่าจะเรียกมันได้ว่าเป็นเหยื่อที่สร้างจากวิชาควบคุมซากศพของนาง โดยใช้พลังของข้าบางส่วน"
L32_1.m_Talk_THA = L33_1
L33_1 = "Ta đoán cô có thể nói rằng đó là mồi nhử được tạo ra nhờ khả năng chiêu hồn của cô ấy, nhờ mượn một phần sức mạnh của ta."
L32_1.m_Talk_VTN = L33_1
L33_1 = "那只是一个通过她的死灵术制成的，分享了我的一部分力量的诱饵。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Ich schätze, man könnte sagen, dass es ein Köder war, der durch ihre Nekromantie mit einem Teil meiner Kraft erschaffen wurde."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Votre amie s'est fait berner par un leurre de sa création, un appât créé en combinant ses techniques de nécromancie à une partie de mes pouvoirs."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP9_ACT4_STAGE4_END@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 378
L33_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "PRINCE_KNIGHT_NULL_NULL"
L33_1.m_CharStrID = L34_1
L33_1.m_Pos = "C"
L34_1 = "그대들을 이리도 완벽하게 속여 넘겼으니, 이번만큼은 그녀도 나의 치하를 받을 자격이 생겼군."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "そなたらをこのように完璧に騙したのだ。今度は彼女も私から称賛を受ける資格を得たな。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "Seeing that you were completely fooled, she has earned my praise for this feat this time..."
L33_1.m_Talk_ENG = L34_1
L34_1 = "竟然完美地騙過你們，看來她這次確實有資格獲得我的稱讚呢。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "เห็นพวกเจ้าโดยหลอกหมดท่าขนาดนี้ ความดีความชอบครั้งนี้ข้าต้องสรรเสริญเสียหน่อยแล้ว"
L33_1.m_Talk_THA = L34_1
L34_1 = "Vì cô đã bị lừa hoàn toàn, cô ấy xứng đáng được ta khen ngợi nhờ thành tích này..."
L33_1.m_Talk_VTN = L34_1
L34_1 = "竟然能够完美地骗过你们，看来这次她也能获得被我夸赞的资格。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Da ich gesehen habe, dass ihr völlig getäuscht wurdet, hat sie sich dieses Mal mein Lob für diese Leistung gehörig verdient ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Et je dois reconnaître que la supercherie a parfaitement fonctionné. Avec ça, Lucrecia remonte un peu dans mon estime."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
