L37_1 = "EP9_ACT4_STAGE4_END@86#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 86
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 378
L36_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L37_1 = "UNIT_PRIDE"
L36_1.m_Face = L37_1
L37_1 = "PRINCE_KNIGHT_NULL_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "m_bCharHologramEffect"
L36_1[L37_1] = true
L37_1 = "그렇다. 너희들은 게임을 멈추기 위해 우리의 성역으로 가려고 했겠지."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "そうだ。そなたらはゲームを止めるために私たちの聖域へ行こうとしたのだろう。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "That’s correct. You were planning on entering our sanctuary to put an end to the game."
L36_1.m_Talk_ENG = L37_1
L37_1 = "沒錯，你們原本是想去我們的聖域停止遊戲吧？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ถูกต้องแล้ว พวกเจ้าวางแผนจะบุกแดนศักดิ์สิทธิ์ของเราเพื่อยุติเกม"
L36_1.m_Talk_THA = L37_1
L37_1 = "Đúng rồi. Các ngươi định xông vào thánh địa của chúng ta để kết thúc trò chơi."
L36_1.m_Talk_VTN = L37_1
L37_1 = "没错。你们一定是想突入我们的圣域结束这场战役。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Das ist richtig. Ihr hattet vor, in unser Heiligtum einzudringen, um dem Spiel ein Ende zu setzen."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Tu commences à comprendre ? Votre objectif était de pénétrer dans notre Sanctuaire pour mettre fin au Jeu..."
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP9_ACT4_STAGE4_END@87#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 87
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 378
L37_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_Face = "UNIT_DESPAIR"
L38_1 = "PRINCE_KNIGHT_NULL_NULL"
L37_1.m_CharStrID = L38_1
L37_1.m_Pos = "C"
L38_1 = "허나 너희들이 갈 곳은 그저 무한한 공허의 공간일 뿐이다."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "だがそなたらの行き先にあるのは、ただ無限に広がった空しい空間だけだ。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "However, the only place you will go to is the infinite void."
L37_1.m_Talk_ENG = L38_1
L38_1 = "不過你們將要去地方，就只有無限虛空的空間。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "แต่ว่า ที่เดียวที่พวกเจ้าจะได้ไปก็มีเพียงความว่างเปล่าอันเป็นนิรันดร์เท่านั้นแหละ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Tuy nhiên, nơi duy nhất cô sẽ đến chỉ là khoảng hư không vô định."
L37_1.m_Talk_VTN = L38_1
L38_1 = "然而你要去的地方，只是一片无垠的虚空。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Aber der einzige Ort, zu dem ihr gehen werdet, ist die unendliche Leere."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Malheureusement pour vous, seul le vide intersidéral vous attend."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
