L38_1.m_CharStrID = L39_1
L38_1.m_Pos = "C"
L39_1 = "그곳에서…… 자신들의 운명을 겸허히 받아들이도록 해라."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "そこで……謙虚に自分たちの運命を受け入れるがいい。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Humbly accept your fate in that place."
L38_1.m_Talk_ENG = L39_1
L39_1 = "在那裡……虛心地接受自己的命運吧！"
L38_1.m_Talk_TWN = L39_1
L39_1 = "จงก้มหน้ายอมรับชะตาตนที่นั่นกันเสียเถิด"
L38_1.m_Talk_THA = L39_1
L39_1 = "Hãy khiêm tốn mà chấp nhận số phận của mình ở nơi đó đi."
L38_1.m_Talk_VTN = L39_1
L39_1 = "希望你们能在那里……虚心接受自己的命运。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Akzeptiert demütig euer Schicksal an diesem Ort."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Vous n'irez pas plus loin, alors acceptez votre sort."
L38_1.m_Talk_FRA = L39_1
