L43_1.m_Crash = 20
L44_1 = "너, 너무 늦었어! 이미 돌입 상태야! 돌아가는 건 불가능해!"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
