L43_1.m_Talk_JPN = L44_1
L44_1 = "I-it’s too late! We already entered the drive state! It’s impossible to turn back now!"
L43_1.m_Talk_ENG = L44_1
L44_1 = "來…來不及啦！已經是進攻狀態！沒辦法回頭！"
L43_1.m_Talk_TWN = L44_1
L44_1 = "มะ-ไม่ทันแล้ว! เราเข้าสู่ขั้นการไดรฟ์แล้ว! ถอยหลังไม่ได้แล้วตอนนี้!"
L43_1.m_Talk_THA = L44_1
L44_1 = "Đ-đã quá muộn rồi! Chúng ta đã vào trạng thái truyền động! Bây giờ không thể quay lại được nữa!"
L43_1.m_Talk_VTN = L44_1
L44_1 = "不行的！太晚了！已经开始进行跳跃了！"
L43_1.m_Talk_SCN = L44_1
L44_1 = "E-es ist zu spät! Wir sind bereits in den Fahrmodus übergegangen! Es ist unmöglich, jetzt umzukehren!"
L43_1.m_Talk_DEU = L44_1
L44_1 = "T-Trop tard ! La séquence est déjà enclenchée, on ne peut plus faire marche arrière !"
L43_1.m_Talk_FRA = L44_1
