L6_1 = "EP9_ACT4_STAGE4_END@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 378
L5_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "UNIT_PRIDE"
L5_1.m_Face = L6_1
L6_1 = "PRINCE_KNIGHT_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "호오, 그때의 그 소년인가?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ほう、あの時の少年か？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Oh? Are you that boy from last time?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "喔？你不是那時候的少年嗎？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "อ้อ? เจ้าคือเด็กคนนั้นเมื่อคราวก่อนรึ?"
L5_1.m_Talk_THA = L6_1
L6_1 = "Ồ? Có phải là anh chàng lần trước đó không?"
L5_1.m_Talk_VTN = L6_1
L6_1 = "噢噢，是那时候的少年吗？"
L5_1.m_Talk_SCN = L6_1
L6_1 = "Oh? Bist du dieser Junge vom letzten Mal?"
L5_1.m_Talk_DEU = L6_1
L6_1 = "Oh ? Tu es le garçon de la dernière fois, n'est-ce pas ?"
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP9_ACT4_STAGE4_END@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 378
L6_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "PRINCE_KNIGHT_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "같은 혈통을 지닌 자로서 나 또한 그대와는 한 번쯤 검을 섞어보고 싶었다."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "同じ血を持つ者として、私もまたそなたとは一度剣を交えたかった。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "As one from the same bloodline, I’ve also wanted to cross swords with you someday."
L6_1.m_Talk_ENG = L7_1
L7_1 = "我們有相同的血統，我原是想與你比劃比劃，"
L6_1.m_Talk_TWN = L7_1
L7_1 = "ในฐานะคนที่มีสายเลือดเดียวกัน ข้าก็หวังจะประดาบกับเจ้าสักวันอยู่เชียว"
L6_1.m_Talk_THA = L7_1
L7_1 = "Là người có cùng huyết thống, ta cũng muốn so kiếm với cậu một lần."
L6_1.m_Talk_VTN = L7_1
L7_1 = "作为同一血脉的人，我也想和你用剑较量一次。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Als jemand aus derselben Blutlinie wollte ich auch eines Tages mit dir die Klingen kreuzen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Toi qui partages le même sang que moi, je serais curieux de croiser mon fer avec le tien."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP9_ACT4_STAGE4_END@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 378
L7_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L7_1.m_bWaitClick = false
L7_1.m_fWaitTime = 0
L8_1 = "PRINCE_KNIGHT_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L8_1 = "허나 시간이 부족하니 빠르게 끝을……"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "だが、時間が足りないから素早く決着を……"
L7_1.m_Talk_JPN = L8_1
L8_1 = "However, since we are short on time, I will put an end─"
L7_1.m_Talk_ENG = L8_1
L8_1 = "不過現在沒時間，要趕快結束……"
L7_1.m_Talk_TWN = L8_1
L8_1 = "แต่ในเมื่อเราไม่ค่อยมีเวลา ข้าจะปลิด..."
L7_1.m_Talk_THA = L8_1
L8_1 = "Tuy nhiên, vì chúng ta không còn thời gian nữa, ta sẽ phải chấm dứt thôi-"
L7_1.m_Talk_VTN = L8_1
L8_1 = "不过，因为时间紧迫，就让我们尽快……"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Da wir aber wenig Zeit haben, werde ich schnell ein Ende setzen -"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Mais le temps joue contre nous, alors je vais devoir abréger tes..."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
