L15_1 = "EP9_ACT4_STAGE4_END@114#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 114
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 378
L14_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "PRINCE_KNIGHT_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L14_1.m_Crash = 30
L15_1 = "이건…… 촉수와…… 붉은 실……?!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "これは……触手と……赤い糸……！？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "What...?! Tentacles... Red strings...?!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "這是……觸鬚……和紅線……？！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "อะไรน่ะ..?! หนวด... เชือกสีแดง...?!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Gì cơ...?! Xúc tu ... Dây đỏ...?!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "这些……触手……还有红线……？！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Was ...?! Tentakeln und ... rote Fäden ...?!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Ces tentacules... ces fils rouges... ?"
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP9_ACT4_STAGE4_END@115#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 115
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 378
L15_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "PRINCE_KNIGHT_NULL_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "C"
L15_1.m_Crash = 15
L16_1 = "설마……! 지식의 탐식자와 인형의 창조자인가? 어떻게 여길!"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "まさか……！　知識の貪食者と人形の創造者か？　どうしてここに！"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Don’t tell me...! The Devourer of Knowledge and the Puppet Creator? How did they get here?!"
L15_1.m_Talk_ENG = L16_1
L16_1 = "難道是……！知識的貪食者和木偶的創造者嗎？她們怎麼會在這裡？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "อย่าบอกนะว่า...! ผู้กลืนกินความรู้กับนักเชิดหุ่นกระบอก? พวกมันมาที่นี่ได้ยังไง?!"
L15_1.m_Talk_THA = L16_1
L16_1 = "Đừng bảo ta ...! Kẻ Múa Rối và Kẻ Ngấu Nghiến Tri Thức? Sao chúng tới đây được?!"
L15_1.m_Talk_VTN = L16_1
L16_1 = "难道……！是知识贪食者和木偶的创造者？她们怎么会！"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Sag mir nicht ...! Die Verschlingerin des Wissens und die Puppenschöpferin? Wie sind sie hierher gekommen?!"
L15_1.m_Talk_DEU = L16_1
L16_1 = "Non... ! Le Dévoreur de connaissances et la marionnettiste ? Comment sont-ils venus ici ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
