L18_1 = "EP9_ACT4_STAGE4_END@117#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 117
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 378
L17_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_LAUGH"
L18_1 = "SEO_YOON_ALT_CA_NULL"
L17_1.m_CharStrID = L18_1
L17_1.m_Pos = "C"
L18_1 = "어머, 죄송해요. 왕자님."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "あら、ごめんなさい。王子様。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Oh my? My apologies, prince."
L17_1.m_Talk_ENG = L18_1
L18_1 = "哎呀，真是不好意思，皇太子殿下。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "โอ้ตาย? ขอโทษนะคร้า คุณเจ้าชาย"
L17_1.m_Talk_THA = L18_1
L18_1 = "Ôi trời? Xin lỗi, thái tử à."
L17_1.m_Talk_VTN = L18_1
L18_1 = "哎呀，抱歉。王子殿下。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Huch, tut mir leid. Eure Hoheit."
L17_1.m_Talk_DEU = L18_1
L18_1 = "Oh ? Mes excuses, mon prince."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "EP9_ACT4_STAGE4_END@118#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 118
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 378
L18_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L19_1 = "SEO_YOON_ALT_CA_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "제가 오다가 오래된 함선 같은 걸 봤는데, 뭔가 잘못 건드렸는지 펑! 하고 터져 버렸지 뭐예요?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "ここに来る途中に、私が古い艦船みたいなのを見たのですが、何か問題でもあったのかボーン！って爆発しちゃったんですよね。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "I came across some type of old ship on my way here, but I must’ve touched something that I shouldn’t have because it went \"BOOM!\" and blew up!"
L18_1.m_Talk_ENG = L19_1
L19_1 = "我來的時候發現一艘很老的艦船，不知道是碰到什麼，結果就砰！一聲爆炸咧？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "ฉันไปเจอยานรบแบบเก่าตอนกำลังมาที่นี่พอดี แต่คงไปแตะอะไรที่ไม่ควรเข้า มันก็เลย “ตู้ม!” ระเบิดกระจุยเลย!"
L18_1.m_Talk_THA = L19_1
L19_1 = "Tôi đã bắt gặp một loại tàu cũ nào đó trên đường tới đây, nhưng hẳn là tôi đã chạm vào thứ gì đó đáng lẽ tôi không nên chạm vì nó đã \"BÙM!\" rồi nổ tung!"
L18_1.m_Talk_VTN = L19_1
L19_1 = "我来的时候看到一艘旧的舰船，不过可能是因为不小心碰到什么，所以“嘭！”的一下就爆炸了！"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Ich bin auf meinem Weg hierher auf eine Art altes Schiff gestoßen, aber ich muss etwas berührt haben, was ich nicht hätte tun sollen, denn es hat „BOOM!\" gemacht und ist explodiert!"
L18_1.m_Talk_DEU = L19_1
L19_1 = "En venant ici, je suis tombée sur un vieux vaisseau... Et quand j'ai voulu l'inspecter, « Boum » ! Il m'a explosé devant les yeux."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
