L21_1 = "UNIT_SERIOUS"
L20_1.m_Face = L21_1
L21_1 = "PRINCE_KNIGHT_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L20_1.m_Crash = 30
L21_1 = "이 도둑고양이 같은 년이 감히!!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "この泥棒猫が！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "You filthy stray cat! How dare you?!!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "你這野貓好大膽子！！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "นังแมวจรโสมมนี่! กล้าดีเยี่ยงไรของเจ้า?!!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Đồ mèo hoang bẩn thỉu! Sao mày dám?!!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "你这个野猫！！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Du dreckige streunende Katze! Wie kannst du es nur wagen?!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Maudit chat errant... Comment oses-tu !"
L20_1.m_Talk_FRA = L21_1
