L23_1 = "EP9_ACT4_STAGE4_END@122#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 122
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 378
L22_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L22_1.m_Pos = "C"
L23_1 = "서윤 양에게는 따로 부탁할 일이 있습니다."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "アオイさんには別の頼みがあります。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "I have something to ask of you separately, Seo Yoon."
L22_1.m_Talk_ENG = L23_1
L23_1 = "徐芸，我另外有事要拜託你。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "ฉันมีอะไรจะขอเป็นการส่วนตัวพอดีเลย คุณซอ ยุน"
L22_1.m_Talk_THA = L23_1
L23_1 = "Tôi có chuyện nhờ riêng cô, Seo Yoon."
L22_1.m_Talk_VTN = L23_1
L23_1 = "徐芸，我要单独拜托你一件事情。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Ich muss dich um etwas anderes bitten, Seo Yoon."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Seo Yoon, j'aimerais vous demander quelque chose."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP9_ACT4_STAGE4_END@123#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 123
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 378
L23_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_LAUGH"
L24_1 = "SEO_YOON_ALT_CA_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "m_bCharHologramEffect"
L23_1[L24_1] = true
L24_1 = "혹시나 해서 말씀드리는데, 부사장님을 따라 자살 특공에 참여해달라는 건 사양이에요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "念のため言っておきますけど、副社長と一緒に自殺特攻に参加するとかは断ります。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Just to put it out there beforehand, if you’re asking me to be a part of your suicide mission, count me out."
L23_1.m_Talk_ENG = L24_1
L24_1 = "我先說，我可沒興趣加入副總的自殺特攻隊。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "บอกก่อนนะคะ ถ้าจะขอให้ไปร่วมปฏิบัติการฆ่าตัวตายด้วยกันละก็ ฉันขอบาย"
L23_1.m_Talk_THA = L24_1
L24_1 = "Phải nói trước, nếu cô dự định yêu cầu tôi tham gia vào nhiệm vụ tự sát này, thì tôi từ chối."
L23_1.m_Talk_VTN = L24_1
L24_1 = "如果是想让我和你一起参加自杀行动的话，我会拒绝的，副总。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Nur um es vorher zu sagen, wenn du mich bittest, an deiner Selbstmordmission teilzunehmen, kannst du nicht auf mich zählen, Vizepräsidentin."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Si c'est pour me demander de vous accompagner dans votre commando suicide, c'est non."
L23_1.m_Talk_FRA = L24_1
L24_1 = {}
L25_1 = "EP9_ACT4_STAGE4_END@124#Talk"
L24_1.m_CutScenKey_Talk = L25_1
L25_1 = 124
L24_1.m_CutScenProcessKey = L25_1
L24_1.m_CutScenID = 378
L24_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L25_1 = "SEO_YOON_ALT_CA_NULL"
L24_1.m_CharStrID = L25_1
L24_1.m_Pos = "C"
L25_1 = "부사장님께 많이 신세를 지긴 했지만, 죽어 달라는 건 아무래도 좀 그렇죠."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "副社長にはたくさんお世話になりましたが、死んでくれというのはちょっと。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "I owe you a lot, but asking me to die is a bit too much."
L24_1.m_Talk_ENG = L25_1
L25_1 = "雖然至今受到副總不少的照顧，但要我去死會不會有點那個？"
L24_1.m_Talk_TWN = L25_1
L25_1 = "ฉันติดหนี้คุณเยอะก็จริง แต่ขอให้ไปตายนี่ก็เกินไปหน่อยค่ะ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Tôi nợ cô rất nhiều, nhưng yêu cầu tôi chết thì hơi quá."
L24_1.m_Talk_VTN = L25_1
L25_1 = "虽然我欠你很多，但要拉着我和你一起送死，就有点过分了。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ich schulde dir viel, aber mich zu bitten, zu sterben, ist ein bisschen zu viel verlangt, Vizepräsidentin."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Je vous dois beaucoup, mais pas au point de mourir pour vos beaux yeux."
L24_1.m_Talk_FRA = L25_1
L25_1 = {}
L26_1 = "EP9_ACT4_STAGE4_END@125#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 125
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 378
L25_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L26_1 = "UNIT_PRIDE"
L25_1.m_Face = L26_1
L25_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L25_1.m_Pos = "C"
L26_1 = "걱정 마세요. 그런 건 저도 기대하지 않으니까."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "大丈夫です。私もそんなことは期待してないですから。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Don’t worry. I never expect you to do something like that."
L25_1.m_Talk_ENG = L26_1
L26_1 = "你放心，我也不期待你會跟我去死。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ไม่ต้องห่วงค่ะ ฉันไม่มีวันขอให้คุณไปทำอะไรแบบนั้นอยู่แล้ว"
L25_1.m_Talk_THA = L26_1
L26_1 = "Đừng lo. Tôi sẽ không bao giờ yêu cầu cô làm điều gì đó như vậy đâu."
L25_1.m_Talk_VTN = L26_1
L26_1 = "别担心。我也不希望那样的事情发生。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Mach dir keine Sorgen. Denn das erwarte ich auch nicht."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Aucune inquiétude. Je n'attends pas un tel sacrifice de votre part."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP9_ACT4_STAGE4_END@126#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 126
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 378
L26_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L26_1.m_Pos = "C"
L27_1 = "엔터프라이즈가 출발하면 서윤 양은 알트 소대와 함께 여기를 떠나 몰래 그 뒤를 따라가세요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "エンタープライズが出発したら、アオイさんはアルト小隊と一緒にここを離れてこっそり後を追ってください。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "When the Enterprise departs, quietly trail behind it with ALT Squad."
L26_1.m_Talk_ENG = L27_1
L27_1 = "等企業號出發後，我要你和阿爾特小隊一起離開這裡，偷偷跟尾隨在後。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "พอเอ็นเตอร์ไพรส์ออกบิน ให้หน่วย ALT ตามไปเงียบๆ นะคะ"
L26_1.m_Talk_THA = L27_1
L27_1 = "Khi Enterprise khởi hành, hãy lặng lẽ theo sau Tiểu Đội ALT."
L26_1.m_Talk_VTN = L27_1
L27_1 = "当企业号出发后，我要你带着阿尔特小队偷偷跟上他们。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Wenn die Enterprise abreist, folge ihr leise mit dem ALT-Trupp, Seo Yoon."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Mais quand l'Enterprise sera parti, je voudrais que vous le suiviez furtivement avec l'escouade ALT."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP9_ACT4_STAGE4_END@127#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 127
L27_1.m_CutScenProcessKey = L28_1
L27_1.m_CutScenID = 378
L27_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L27_1.m_bWaitClick = true
L27_1.m_fWaitTime = 0
L27_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L27_1.m_Pos = "C"
L28_1 = "적들도 엔터프라이즈에 관심이 집중될 테니 그리 어렵지는 않을 겁니다."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "敵もエンタープライズに注目するはずですから、そこまで難しくはないはずです。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Since the enemy will be focused on the Enterprise, it shouldn’t be too difficult."
L27_1.m_Talk_ENG = L28_1
L28_1 = "敵人的視線應該也會集中在企業號上，我想應該不難。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "เพราะพวกศัตรูคงสนใจแต่เอ็นเตอร์ไพรส์ คงทำได้ไม่ยาก"
L27_1.m_Talk_THA = L28_1
L28_1 = "Vì kẻ thù sẽ tập trung vào Enterprise, việc này không quá khó."
L27_1.m_Talk_VTN = L28_1
L28_1 = "敌人也会被企业号吸引注意力，所以应该不会太难。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Die Feinde werden sich auch auf die Enterprise konzentrieren, also wird es nicht allzu schwierig sein."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Vu que l'ennemi aura les yeux rivés sur le vaisseau, ça ne devrait pas être trop difficile."
L27_1.m_Talk_FRA = L28_1
L28_1 = {}
L29_1 = "EP9_ACT4_STAGE4_END@128#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 128
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 378
L28_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L28_1.m_Face = "UNIT_HATE"
L29_1 = "SEO_YOON_ALT_CA_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "m_bCharHologramEffect"
L28_1[L29_1] = true
L28_1.m_Crash = 20
L29_1 = "……어째서죠?"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "……どうしてですか？"
L28_1.m_Talk_JPN = L29_1
L29_1 = "...But why, though?"
L28_1.m_Talk_ENG = L29_1
L29_1 = "……為什麼？"
L28_1.m_Talk_TWN = L29_1
L29_1 = "...แต่เพื่ออะไรล่ะ?"
L28_1.m_Talk_THA = L29_1
L29_1 = "... Nhưng dù thế, tại sao chứ?"
L28_1.m_Talk_VTN = L29_1
L29_1 = "……为什么？"
L28_1.m_Talk_SCN = L29_1
L29_1 = "... Aber warum?"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Mais... pourquoi ?"
L28_1.m_Talk_FRA = L29_1
L29_1 = {}
L30_1 = "EP9_ACT4_STAGE4_END@129#Talk"
L29_1.m_CutScenKey_Talk = L30_1
L30_1 = 129
L29_1.m_CutScenProcessKey = L30_1
L29_1.m_CutScenID = 378
L29_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L30_1 = "SEO_YOON_ALT_CA_NULL"
L29_1.m_CharStrID = L30_1
L29_1.m_Pos = "C"
L30_1 = "저희들까지 빠지면 부사장님…… 분명 죽을 텐데요."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "私たちまで外れると副社長……きっと死にますよ。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "If we pull out, then you... You’ll die."
L29_1.m_Talk_ENG = L30_1
L30_1 = "我們也離開的話，副總應該……必死無疑。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "ถ้าเราไปแล้วคุณ... คุณจะตายเอานะ"
L29_1.m_Talk_THA = L30_1
L30_1 = "Nếu chúng ta rút đi, thì cô... Cô sẽ chết."
L29_1.m_Talk_VTN = L30_1
L30_1 = "如果我们也离开……副总你……你肯定会死的。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "Ohne uns wirst du definitiv sterben, Vizepräsidentin ..."
L29_1.m_Talk_DEU = L30_1
L30_1 = "Si on vous laisse y aller seule, alors... vous mourrez."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "EP9_ACT4_STAGE4_END@130#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 130
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 378
L30_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_IDLE"
L31_1 = "SEO_YOON_ALT_CA_NULL"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "제가 현실적인 여자이긴 하지만, 성의껏 부탁하신다면 지원해 드리는 것 정도는……"
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "私は現実的な女ではありますけど、誠心誠意頼むということでしたら援護ぐらいは……"
L30_1.m_Talk_JPN = L31_1
L31_1 = "I may be a realistic person, but if you ask sincerely, then I can at least provide support..."
L30_1.m_Talk_ENG = L31_1
L31_1 = "雖然我很現實，但副總誠心拜託我的話，這個忙我是能幫……"
L30_1.m_Talk_TWN = L31_1
L31_1 = "ฉันอาจเป็นคนที่อยู่กับความเป็นจริง แต่ถ้าคุณขอกันอย่างจริงใจ อย่างน้อยฉันก็เป็นกำลังสนับสนุนให้ได้..."
L30_1.m_Talk_THA = L31_1
L31_1 = "Tôi có thể là một người thực tế, nhưng nếu cô nhờ vả chân thành, thì ít nhất tôi cũng có thể hỗ trợ..."
L30_1.m_Talk_VTN = L31_1
L31_1 = "虽然我是个挺现实的人，但如果你诚心拜托我，我也可以留下来……"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Obwohl ich eine realistische Frau bin, kann ich nicht anders, als dich zu unterstützen, wenn du mich darum bittest ..."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Enfin même avec un esprit pragmatique comme le mien, si c'est vraiment ce que vous voulez..."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "EP9_ACT4_STAGE4_END@131#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 131
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 378
L31_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L31_1.m_bWaitClick = true
