L31_1.m_Face = "UNIT_IDLE"
L31_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L31_1.m_Pos = "C"
L32_1 = "아니요. 그보다 더 중요한 일입니다."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "いいえ。それよりもっと大事なことです。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "No, this is more important."
L31_1.m_Talk_ENG = L32_1
L32_1 = "聽我說，這件事非常重要。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ไม่ค่ะ เรื่องนี้สำคัญกว่า"
L31_1.m_Talk_THA = L32_1
L32_1 = "Không, điều này quan trọng hơn."
L31_1.m_Talk_VTN = L32_1
L32_1 = "不。听我说，我有更重要的事情需要你去做。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Nein, das ist wichtiger."
L31_1.m_Talk_DEU = L32_1
L32_1 = "Vous vous trompez. C'est autre chose."
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP9_ACT4_STAGE4_END@132#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 132
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 378
L32_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L32_1.m_Pos = "C"
L33_1 = "마왕들이 직접 나타나지 않는 건 분명 이유가 있어서입니다."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "魔王たちが直接現れないことにはきっと何か理由があるはずです。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "There will definitely be a reason why the Demon Lords have not appeared in person."
L32_1.m_Talk_ENG = L33_1
L33_1 = "魔王沒出現肯定是有原因的。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "คงจะมีเหตุผลมากมายที่เหล่าเจ้าแห่งดีม่อนไม่ปรากฏตัวกันออกมา"
L32_1.m_Talk_THA = L33_1
L33_1 = "Chắc chắn sẽ có một lý do tại sao Chúa Quỷ không trực tiếp tham chiến."
L32_1.m_Talk_VTN = L33_1
L33_1 = "魔王们没有亲自出现，一定是有原因的。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Es wird definitiv einen Grund dafür geben, warum die Dämonenfürsten nicht persönlich erschienen sind."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Si les Seigneurs démons ne sont toujours pas ici, il doit y avoir une raison."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "EP9_ACT4_STAGE4_END@133#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 133
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 378
L33_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L33_1.m_Pos = "C"
L34_1 = "추측건대…… 아마도 지난번 주시윤 군의 납치 사건에서 저들이 획득한 마왕의 관들 중 하나."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "推測するに……たぶんこの前のアキヤマ・シリュウさんの拉致事件で彼らが手に入れた魔王の冠の一つ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "This is only my guess, but one of the Demon Lords’ coffins that they had acquired while kidnapping Joo Shiyoon..."
L33_1.m_Talk_ENG = L34_1
L34_1 = "根據我的猜測……他們應該是將上次周時雲綁架事件中獲得的其中一個魔王之棺，"
L33_1.m_Talk_TWN = L34_1
L34_1 = "นี่ฉันเดาเอาเองนะคะ แต่โลงศพใบหนึ่งของเจ้าแห่งดีม่อนที่เราได้มาตอนเหตุการณ์ลักพาตัวจู ชิยุน..."
L33_1.m_Talk_THA = L34_1
L34_1 = "Đây chỉ là suy đoán của tôi thôi, nhưng một trong những quan tài mà Chúa Quỷ đã có được trong vụ bắt cóc Joo Shiyoon..."
L33_1.m_Talk_VTN = L34_1
L34_1 = "我猜，他们应该是使用了上一次绑架周时云时获得的其中一个魔王之棺。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "Dies ist nur meine Vermutung, aber einer der Särge der Dämonenfürsten, die sie beim Entführen von Joo Shiyoon erworben haben ..."
L33_1.m_Talk_DEU = L34_1
L34_1 = "Ce n'est qu'une supposition, mais il y a ce cercueil qu'ils ont volé aux Seigneurs démons lors de l'enlèvement de Charles, la dernière fois..."
L33_1.m_Talk_FRA = L34_1
L34_1 = {}
L35_1 = "EP9_ACT4_STAGE4_END@134#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 134
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 378
L34_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L34_1.m_Pos = "C"
L35_1 = "코핀 오브 네헤모트를 수리하여 함선에 내장된 봉인 기능을 사용했을 겁니다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "コフィン・オブ・ネヘモトを修理し、艦船に内蔵された封印機能を使ったのでしょう。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "The Coffin of Nehemoth. They must have repaired it and used the ship’s internal sealing function."
L34_1.m_Talk_ENG = L35_1
L35_1 = "也就是科芬之貝赫莫特進行修理後，再使用艦船內建的封印功能。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "มันคือโลงศพของนีฮีมอท พวกเขาต้องซ่อมโลงนั่นและใช้ฟังก์ชันการผนึกภายในของยาน"
L34_1.m_Talk_THA = L35_1
L35_1 = "Quan tài của Nehemoth. Chắc hẳn chúng đã sửa chữa nó và sử dụng chức năng phong ấn bên trong của con tàu."
L34_1.m_Talk_VTN = L35_1
L35_1 = "也就是涅赫摩斯之棺，他们应该是修好了舰船中的封印功能。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Möglicherweise haben sie den Sarg von Nehemoth repariert und die eingebaute Versiegelungsfunktion des Schiffs verwendet."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Le Coffin de Nehemoth. Ils ont dû le réparer et utiliser la fonctionnalité de scellage intégrée."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "EP9_ACT4_STAGE4_END@135#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 135
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 378
L35_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L35_1.m_Pos = "C"
L36_1 = "그것 때문에 다른 마왕들이 접근하지 못하는 거죠."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "それのせいで他の魔王が近づけないわけです。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "The other Demon Lords are unable to approach because of that."
L35_1.m_Talk_ENG = L36_1
L36_1 = "就是因為這樣，其他魔王才無法靠近。"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เพราะแบบนั้นเจ้าแห่งดีม่อนตนอื่นๆ เลยเข้ามาใกล้ไม่ได้"
L35_1.m_Talk_THA = L36_1
L36_1 = "Vì lẽ đó mà các Chúa Quỷ khác không thể tiếp cận."
L35_1.m_Talk_VTN = L36_1
L36_1 = "因为这样，魔王们才无法接近。"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Die anderen Dämonenfürsten können sich deshalb nicht nähern."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Et à cause de ça, les autres Seigneurs démons sont incapables de s'en approcher."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
L37_1 = "EP9_ACT4_STAGE4_END@136#Talk"
L36_1.m_CutScenKey_Talk = L37_1
L37_1 = 136
L36_1.m_CutScenProcessKey = L37_1
L36_1.m_CutScenID = 378
L36_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_Face = "UNIT_SURPRISE"
L37_1 = "SEO_YOON_ALT_CA_NULL"
L36_1.m_CharStrID = L37_1
L36_1.m_Pos = "C"
L37_1 = "m_bCharHologramEffect"
L36_1[L37_1] = true
L36_1.m_Crash = 15
L37_1 = "그때의 그 도시 함선 말인가요……?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "あの時の都市艦船のことですか……？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "You mean the city ship we came across that time...?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "你是說那時候的城市艦船嗎……？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "คุณหมายถึงยานรบรูปร่างเมืองที่เราเจอตอนนั้นเหรอ...?"
L36_1.m_Talk_THA = L37_1
L37_1 = "Ý cô là con tàu thành phố mà chúng ta đã đi qua lần đó ư...?"
L36_1.m_Talk_VTN = L37_1
L37_1 = "是说上次那个也叫作“科芬(Coffin)”的城市舰船吗……？"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Du meinst das Stadtschiff, auf das wir damals gestoßen sind ...?"
L36_1.m_Talk_DEU = L37_1
L37_1 = "Vous voulez parler de ce vaisseau construit à l'image d'une ville médiévale... ?"
L36_1.m_Talk_FRA = L37_1
L37_1 = {}
L38_1 = "EP9_ACT4_STAGE4_END@137#Talk"
L37_1.m_CutScenKey_Talk = L38_1
L38_1 = 137
L37_1.m_CutScenProcessKey = L38_1
L37_1.m_CutScenID = 378
L37_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L37_1.m_bWaitClick = true
L37_1.m_fWaitTime = 0
L37_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L37_1.m_Pos = "C"
L38_1 = "맞아요. 만약 이번 작전이 잘 통한다면 그대로 전장에서 이탈하세요."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "はい。もし今回の作戦がうまくいったらそのまま戦場から離脱してください。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "That is correct. If this operation goes smoothly, follow them out of the battlefield."
L37_1.m_Talk_ENG = L38_1
L38_1 = "沒錯，若是作戰成功，那你就順勢離開戰場。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "ใช่ ถ้าปฏิบัติการเป็นไปอย่างราบรื่น ก็ตามพวกเขาไปในสนามรบนะคะ"
L37_1.m_Talk_THA = L38_1
L38_1 = "Đúng. Nếu tác chiến này suôn sẻ, hãy đi theo họ để rời khỏi chiến trường."
L37_1.m_Talk_VTN = L38_1
L38_1 = "没错。如果这次的作战成功，那么你就顺势跟着德尔塔部队离开战场。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "Genau. Wenn diese Operation reibungslos verläuft, folge ihnen aus dem Schlachtfeld."
L37_1.m_Talk_DEU = L38_1
L38_1 = "Correct. Si l'opération se déroule sans accroc, vous n'aurez qu'à évacuer après le combat."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
L39_1 = "EP9_ACT4_STAGE4_END@138#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 138
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 378
L38_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "UNIT_SERIOUS"
L38_1.m_Face = L39_1
L38_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L38_1.m_Pos = "C"
L39_1 = "하지만 무언가 예상 외의 상황이 벌어진다면……"
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ですが、何か予想外の事態が発生したら……"
L38_1.m_Talk_JPN = L39_1
L39_1 = "However, if something unexpected happens..."
L38_1.m_Talk_ENG = L39_1
L39_1 = "但若有突發狀況……"
L38_1.m_Talk_TWN = L39_1
L39_1 = "แต่ยังไง ถ้าเกิดเรื่องไม่คาดคิดขึ้น..."
L38_1.m_Talk_THA = L39_1
L39_1 = "Tuy nhiên, nếu có điều gì đó không mong muốn xảy ra..."
L38_1.m_Talk_VTN = L39_1
L39_1 = "不过如果出现预料之外的情况……"
L38_1.m_Talk_SCN = L39_1
L39_1 = "Wenn jedoch etwas Unerwartetes passiert ..."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Cependant, si quelque chose d'inattendu se produit..."
L38_1.m_Talk_FRA = L39_1
L39_1 = {}
L40_1 = "EP9_ACT4_STAGE4_END@139#Talk"
L39_1.m_CutScenKey_Talk = L40_1
L40_1 = 139
L39_1.m_CutScenProcessKey = L40_1
L39_1.m_CutScenID = 378
L39_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L39_1.m_bWaitClick = true
L39_1.m_fWaitTime = 0
L39_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L39_1.m_Pos = "C"
L40_1 = "코핀 오브 네헤모트를 발견해 파괴하세요."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "コフィン・オブ・ネヘモトを探して破壊してください。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "Find and destroy the Coffin of Nehemoth."
L39_1.m_Talk_ENG = L40_1
L40_1 = "那就找到科芬之貝赫莫特後破壞它。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "ให้ตามหาและทำลายโลงศพของนีฮีมอทซะค่ะ"
L39_1.m_Talk_THA = L40_1
L40_1 = "Hãy tìm và phá hủy Quan Tài Của Nehemoth."
L39_1.m_Talk_VTN = L40_1
L40_1 = "就请你找到涅赫摩斯之棺并将其破坏。"
L39_1.m_Talk_SCN = L40_1
L40_1 = "Finde und zerstöre den Sarg von Nehemoth."
L39_1.m_Talk_DEU = L40_1
L40_1 = "Trouvez le Coffin de Nehemoth, et détruisez-le."
L39_1.m_Talk_FRA = L40_1
L40_1 = {}
L41_1 = "EP9_ACT4_STAGE4_END@140#Talk"
L40_1.m_CutScenKey_Talk = L41_1
L41_1 = 140
L40_1.m_CutScenProcessKey = L41_1
L40_1.m_CutScenID = 378
L40_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L40_1.m_bWaitClick = true
L40_1.m_fWaitTime = 0
L40_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L40_1.m_Pos = "C"
L41_1 = "격침시킬 필요는 없습니다. 작은 손상만 줘도 괜찮아요."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "撃沈させる必要はありません。小さな傷でもいいのです。"
L40_1.m_Talk_JPN = L41_1
L41_1 = "There is no need to completely destroy it. Minor damage should be more than enough to do the job."
L40_1.m_Talk_ENG = L41_1
L41_1 = "不需要擊落它，只有小小的毀損也無所謂。"
L40_1.m_Talk_TWN = L41_1
L41_1 = "ไม่ต้องทำลายให้สิ้นซากก็ได้นะ แค่ความเสียหายเล็กน้อยก็พอแล้ว"
L40_1.m_Talk_THA = L41_1
L41_1 = "Không cần phải hủy diệt nó hoàn toàn. Phá hỏng một chút là quá đủ rồi."
L40_1.m_Talk_VTN = L41_1
L41_1 = "没必要击沉。只需要简单的损伤。"
L40_1.m_Talk_SCN = L41_1
L41_1 = "Es besteht keine Notwendigkeit, ihn vollständig zu zerstören. Geringfügige Schäden sollten mehr als genug sein."
L40_1.m_Talk_DEU = L41_1
L41_1 = "Vous n'aurez pas besoin de l'anéantir complètement, des dommages mineurs devraient suffire."
L40_1.m_Talk_FRA = L41_1
L41_1 = {}
L42_1 = "EP9_ACT4_STAGE4_END@141#Talk"
L41_1.m_CutScenKey_Talk = L42_1
L42_1 = 141
L41_1.m_CutScenProcessKey = L42_1
L41_1.m_CutScenID = 378
L41_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L41_1.m_bWaitClick = true
L41_1.m_fWaitTime = 0
L41_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L41_1.m_Pos = "C"
L42_1 = "봉인 기능에 약간의 틈이라도 생긴다면…… 마왕들은 분명 그 틈을 비집고 들어올 테니까요."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "封印機能に少しでも隙ができたら……魔王たちはきっとその隙に割り込むでしょうから。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "If there is even the slightest crack in the sealing function, the Demon Lords will surely take advantage of that."
L41_1.m_Talk_ENG = L42_1
L42_1 = "只要封印功能出現一點縫隙……魔王一定會藉由那個縫隙出現的。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "ขอแค่มีรอยแตกเล็กๆ ในฟังก์ชันการผนึก พวกเจ้าแห่งดีม่อนต้องฉวยโอกาสจากจุดนั้นแน่"
L41_1.m_Talk_THA = L42_1
L42_1 = "Nếu có một vết nứt, dù là nhỏ nhất trong chức năng phong ấn, các Chúa Quỷ chắc chắn sẽ tận dụng triệt để."
L41_1.m_Talk_VTN = L42_1
L42_1 = "只要封印功能出现任何微小的漏洞……魔王们就可以通过漏洞进来了。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "Wenn es auch nur den kleinsten Riss in der Versiegelungsfunktion gibt, werden die Dämonenfürsten das sicher ausnutzen."
L41_1.m_Talk_DEU = L42_1
L42_1 = "La moindre fissure dans le système de scellage devrait permettre aux Seigneurs démons de s'engouffrer dans la brèche."
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
