L43_1.m_Face = "UNIT_IDLE"
L43_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L43_1.m_Pos = "C"
L44_1 = "사장님께서 만들어 주신 블랙홀 엔진 추적기입니다."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "社長が作ってくださったブラックホールエンジン追跡装置です。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "This is the Blackhole Engine Detector made by Boss."
L43_1.m_Talk_ENG = L44_1
L44_1 = "這是老闆製作的黑洞引擎追蹤器。"
L43_1.m_Talk_TWN = L44_1
L44_1 = "นี่คืออุปกรณ์ตรวจจับเครื่องยนต์พลังหลุมดำที่บอสเราทำขึ้น"
L43_1.m_Talk_THA = L44_1
L44_1 = "Đây là Máy Dò Động Cơ Lỗ Đen mà ông chủ của chúng tôi chế tạo."
L43_1.m_Talk_VTN = L44_1
L44_1 = "这是老板制造的黑洞引擎搜索器。"
L43_1.m_Talk_SCN = L44_1
L44_1 = "Dies ist ein Tracker für Wurmlöcher, der vom Boss hergestellt wurde."
L43_1.m_Talk_DEU = L44_1
L44_1 = "Tenez, prenez ce détecteur de moteurs à trou noir préparé par notre directeur."
L43_1.m_Talk_FRA = L44_1
L44_1 = {}
L45_1 = "EP9_ACT4_STAGE4_END@144#Talk"
L44_1.m_CutScenKey_Talk = L45_1
L45_1 = 144
L44_1.m_CutScenProcessKey = L45_1
