L44_1.m_CharStrID = "LEESOOYEON_WING_NULL_NULL"
L44_1.m_Pos = "C"
L45_1 = "이걸 사용하면 코핀 오브 네헤모트의 위치를 찾을 수 있을 거예요."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "これを使えば、コフィン・オブ・ネヘモトの位置を見つけられるはずです。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "You can use this to locate the Coffin of Nehemoth."
L44_1.m_Talk_ENG = L45_1
L45_1 = "用這個應該可以找到科芬之貝赫莫特的位置。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "คุณใช้หาตำแหน่งโลงศพของนีฮีมอทได้ค่ะ"
L44_1.m_Talk_THA = L45_1
L45_1 = "Cô có thể sử dụng nó để xác định vị trí Quan Tài Của Nehemoth."
L44_1.m_Talk_VTN = L45_1
L45_1 = "使用这个应该可以找到涅赫摩斯之棺的位置。"
L44_1.m_Talk_SCN = L45_1
L45_1 = "Du kannst ihn verwenden, um den Sarg von Nehemoth ausfindig zu machen."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Il vous aidera à localiser le Coffin de Nehemoth."
L44_1.m_Talk_FRA = L45_1
L45_1 = {}
