L46_1.m_Pos = "C"
L47_1 = "알겠습니다. 그 정도라면 맡겨 두세요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "わかりました。そのくらいなら任せてください。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Understood. Leave this to us."
L46_1.m_Talk_ENG = L47_1
L47_1 = "好，這點小事就包在我身上！"
L46_1.m_Talk_TWN = L47_1
L47_1 = "เข้าใจแล้ว ให้พวกเราจัดการเอง"
L46_1.m_Talk_THA = L47_1
L47_1 = "Hiểu rồi. Cứ để đó cho tôi."
L46_1.m_Talk_VTN = L47_1
L47_1 = "好。那就交给我吧。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Verstanden. Überlass das nur uns."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Compris. On fera le nécessaire."
L46_1.m_Talk_FRA = L47_1
