L4_1 = "EDEL_ESPR_SHADOW_NULL"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "L"
L4_1 = "안녕하세요. 황태자님. 오랜만에 뵙네요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "こんにちは。皇太子様。お久しぶりですね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Hello, Crown Prince. It’s been a long time."
L3_1.m_Talk_ENG = L4_1
L4_1 = "皇太子殿下，好久不見。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ว่าไงคะ มกุฎราชกุมาร ไม่เจอกันนานเลย"
L3_1.m_Talk_THA = L4_1
L4_1 = "Xin chào, Thái Tử. Lâu quá chưa gặp."
L3_1.m_Talk_VTN = L4_1
L4_1 = "好久不见，皇太子殿下。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "Hallo, Kronprinz. Es ist lange her."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Bonjour, prince héritier. Ça faisait longtemps."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP9_ACT4_STAGE4_END@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 378
L4_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_DESPAIR"
L5_1 = "EDEL_ESPR_SHADOW_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "L"
L5_1 = "그런데…… 동맹을 맺어 놓고 이렇게 불결한 결계로 저희들의 출입을 막으시면 곤란하답니다."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "でも……同盟を結んでおいて、このような不潔な結界で我々の出入りを遮られると困るのです。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "But... It’s awkward if you block our entry using that dreadful barrier after making an alliance with us."
L4_1.m_Talk_ENG = L5_1
L5_1 = "不過……我們不是結盟的關係嗎？怎麼可以用這種不道德的結界阻止我們進出呢？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "แต่แหม... หลังจากร่วมเป็นพันธมิตรกับเราแล้วกลับเอาบาเรียน่ากลัวๆ พรรค์นั้นมาขวางไม่ให้เราเข้ามานี่มันน่าอึดอัดอยู่นะคะ"
L4_1.m_Talk_THA = L5_1
L5_1 = "Có điều...Đã liên minh rồi, lại còn dùng kết giới bẩn thỉu đó ngăn chúng tôi tiến vào thì thật đáng giận."
L4_1.m_Talk_VTN = L5_1
L5_1 = "我们不是同盟吗？为什么要用这么肮脏的结界阻止我们过来？这样的举动很让人生气呢。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Jedoch … Es wäre schwierig, wenn Sie ein Bündnis schließen und unseren Zugang mit einer so schmutzigen Barriere blockieren würden."
L4_1.m_Talk_DEU = L5_1
L5_1 = "Mais je suis curieuse... à quoi pensiez-vous en utilisant cette barrière pour nous empêcher de venir ici ? Je croyais que nous formions une alliance, vous et nous ?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP9_ACT4_STAGE4_END@155#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 155
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 378
L5_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L6_1 = "SERAPEL_QLIPHOTH_NULL_NULL"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "R"
L6_1 = "……그렇다."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "……そうよ。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "...She's right."
L5_1.m_Talk_ENG = L6_1
L6_1 = "……沒錯。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "...จริงของนาง"
L5_1.m_Talk_THA = L6_1
L6_1 = "...Cô ấy nói đúng."
L5_1.m_Talk_VTN = L6_1
L6_1 = "……没错。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "... Sie hat recht."
L5_1.m_Talk_DEU = L6_1
L6_1 = "... Elle a raison."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "EP9_ACT4_STAGE4_END@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 378
L6_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L7_1 = "SERAPEL_QLIPHOTH_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "R"
L7_1 = "저주받은 늑대는 나에게 지고한 고통을 선사해 줄 귀중한 존재."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "呪われし狼は私に至極の苦しみを与えてくれる貴重な存在。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "The Cursed Wolf is a precious being that will gift me with delectable pain."
L6_1.m_Talk_ENG = L7_1
L7_1 = "受詛咒的狼是帶給我無比痛苦的寶貝，"
L6_1.m_Talk_TWN = L7_1
L7_1 = "นางหมาป่าต้องสาปเป็นสิ่งมีชีวิตทรงคุณค่าที่จะมอบความเจ็บปวดอันโอชะเป็นของขวัญแก่ข้า"
L6_1.m_Talk_THA = L7_1
L7_1 = "Con Sói Bị Nguyền Rủa là một sinh vật quý giá sẽ mang đến cho tôi những nỗi đau không gì sánh được."
L6_1.m_Talk_VTN = L7_1
L7_1 = "被诅咒的狼是会给我带来至高无上痛苦的珍贵存在。"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Der verfluchte Wolf ist ein kostbares Wesen, das mir den köstlichsten Schmerz bereiten wird."
L6_1.m_Talk_DEU = L7_1
L7_1 = "La Louve maudite est un être précieux, et je suis impatiente de me délecter de sa douleur."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
