L7_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "SERAPEL_QLIPHOTH_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "R"
L8_1 = "그런 소중한 것을 홀로 독차지하려는 건 인정할 수 없지."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "そんな大事なものを独り占めしようなんて、認められないわ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I cannot accept your impunity in trying to monopolize such a precious thing."
L7_1.m_Talk_ENG = L8_1
L8_1 = "我可不允許你獨佔這個寶貝。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ข้ามิอาจอภัยโทษที่เจ้าพยายามยึดครองของมีค่าเช่นนี้ไว้คนเดียวได้"
L7_1.m_Talk_THA = L8_1
L8_1 = "Tôi không thể coi anh vô tội khi âm mưu độc chiếm một thứ quý giá như vậy được."
L7_1.m_Talk_VTN = L8_1
L8_1 = "试图独占如此珍贵的东西，是无法容忍的行为。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Es ist inakzeptabel, zu versuchen, so etwas Kostbares für sich zu behalten."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Je ne peux pas vous laisser la monopoliser en toute impunité."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
