L10_1 = "UNIT_SERIOUS"
L9_1.m_Face = L10_1
L10_1 = "FX_COMBAT_ALL_FOOT_STEP_LANDING_SMALL_02"
L9_1.m_StartFXSoundName = L10_1
L10_1 = "PRINCE_KNIGHT_NULL_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L9_1.m_Crash = 10
L10_1 = "왕을 참칭하는 괴물 년들이 감히……!"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "王を僭称する化け物どもが……！"
L9_1.m_Talk_JPN = L10_1
L10_1 = "You lord-pretending monsters, how dare you...?!"
L9_1.m_Talk_ENG = L10_1
L10_1 = "自封為王的怪物女竟敢……！"
L9_1.m_Talk_TWN = L10_1
L10_1 = "ไอ้พวกสัตว์ประหลาดที่แสร้งทำตนเป็นเจ้า กล้าดีเยี่ยงไรกัน...?!"
L9_1.m_Talk_THA = L10_1
L10_1 = "Đồ quái vật giả danh chúa tể, sao các ngươi dám...?!"
L9_1.m_Talk_VTN = L10_1
L10_1 = "你们这些自称为王的怪物！竟然敢……！"
L9_1.m_Talk_SCN = L10_1
L10_1 = "Ihr Monster, die vorgebt Könige zu sein, wie könnt ihr es nur wagen ...?!"
L9_1.m_Talk_DEU = L10_1
L10_1 = "Vous... comment osez-vous, misérables monstres... ?!"
L9_1.m_Talk_FRA = L10_1
