L14_1 = "SERAPEL_QLIPHOTH_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "R"
L13_1.m_Crash = 15
L14_1 = "아아, 꽤 나쁘지 않은 고통이었어."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "ああ、なかなか悪くない苦しみだった。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Aahh... That pain was quite acceptable."
L13_1.m_Talk_ENG = L14_1
L14_1 = "啊啊～這個痛苦的感覺還不錯。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "อาาาห์... ความเจ็บปวดนั่นก็พอจะรับได้อยู่นะ"
L13_1.m_Talk_THA = L14_1
L14_1 = "Aahh ... Nỗi đau đó cũng không tệ đâu."
L13_1.m_Talk_VTN = L14_1
L14_1 = "啊啊，算是一种相当不错的痛苦。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Aahh ... Dieser Schmerz war recht akzeptabel."
L13_1.m_Talk_DEU = L14_1
L14_1 = "Aah... cette douleur était tout à fait acceptable."
L13_1.m_Talk_FRA = L14_1
L14_1 = {}
L15_1 = "EP9_ACT4_STAGE4_END@164#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 164
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 378
L14_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L15_1 = "SERAPEL_QLIPHOTH_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "R"
L15_1 = "하지만 늑대가 줄 고통에 비하면…… 하찮기 짝이 없구나."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "でも狼が与えてくれる苦しみに比べれば……くだらないわね。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "However, in comparison to the pain that the Wolf will bring me... Pathetic."
L14_1.m_Talk_ENG = L15_1
L15_1 = "但是……完全比不上狼帶給我的痛苦。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "แต่ถ้าเทียบกับความเจ็บปวดที่นางหมาป่าจะมอบให้ข้าแล้ว... ช่างน่าสังเวชนัก"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tuy nhiên, so với nỗi đau mà con sói sẽ mang lại cho tôi thì... thật thảm hại."
L14_1.m_Talk_VTN = L15_1
L15_1 = "但与狼所给予的痛苦相比……它是如此微不足道。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Aber im Vergleich zu dem Schmerz, den der Wolf mir bringen wird ... Erbärmlich."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Mais face à celle que pourrait me procurer la louve... ce n'est rien de comparable."
L14_1.m_Talk_FRA = L15_1
L15_1 = {}
L16_1 = "EP9_ACT4_STAGE4_END@165#Talk"
L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 378
L15_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L16_1 = "EDEL_ESPR_SHADOW_NULL"
L15_1.m_CharStrID = L16_1
L15_1.m_Pos = "L"
L16_1 = "사도이면서 마왕의 힘을 일부 양도받은 건가요? 아니면 그 진룡의 검의 힘일까요?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "使徒でありながら魔王の力を一部授けられたのですか？　それともその真龍の剣の力なのでしょうか？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "Were you bestowed with a part of a Demon Lord’s power as an apostle, or was this the power of the Blade of True Dragon?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "因為是使徒，同時又得到部分魔王的力量嗎？還是那把真龍之劍的力量？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "นี่คุณได้รับพลังของเจ้าแห่งดีม่อนมาในฐานะสาวก หรือนี่คือพลังของดาบแห่งเลือดมังกรที่แท้จริงกันนะคะ?"
L15_1.m_Talk_THA = L16_1
L16_1 = "Anh được ban tặng một phần sức mạnh của Chúa Quỷ khi trở thành tông đồ cho chúng, hay đây là sức mạnh của thanh Kiếm chứa máu rồng thực sự?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "这到底是身为使徒所得到的一部分魔王的力量呢？还是真龙之剑所给予的力量？真想了解呢。"
L15_1.m_Talk_SCN = L16_1
L16_1 = "Wurde Ihnen als Apostel ein Teil der Macht eines Dämonenfürsten verliehen, oder war dies die Macht der Klinge des wahren Drachen?"
L15_1.m_Talk_DEU = L16_1
L16_1 = "En tant qu'apôtre d'un Seigneur démon, vous a-t-il conféré une partie de sa puissance ? Ou s'agit-il là du pouvoir du sang de dragon ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "EP9_ACT4_STAGE4_END@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 378
L16_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L17_1 = "EDEL_ESPR_SHADOW_NULL"
L16_1.m_CharStrID = L17_1
L16_1.m_Pos = "L"
L17_1 = "어느 쪽이나 지금의 저희로서는 조금 번거로울 것 같네요."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "どちらにせよ、今の我々にとっては少し厄介そうですね。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Whichever the case, it will be difficult for us."
L16_1.m_Talk_ENG = L17_1
L17_1 = "不管是哪一種，對現在的我們而言都會有點麻煩呢。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "แต่จะแบบไหน ก็ทำเราลำบากทั้งนั้น"
L16_1.m_Talk_THA = L17_1
L17_1 = "Dù thế nào thì cũng sẽ khó cho chúng ta."
L16_1.m_Talk_VTN = L17_1
L17_1 = "不管怎样，现在对我们来说似乎都有点麻烦。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Was auch immer der Fall ist, es wird für uns schwierig sein."
L16_1.m_Talk_DEU = L17_1
L17_1 = "Quelle que soit votre réponse, on ne peut pas vraiment vous laisser faire."
L16_1.m_Talk_FRA = L17_1
L17_1 = {}
