L19_1 = "EP9_ACT4_STAGE4_END@168#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 168
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 378
L18_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_LAUGH"
L19_1 = "EDEL_ESPR_SHADOW_NULL"
L18_1.m_CharStrID = L19_1
L18_1.m_Pos = "C"
L19_1 = "하지만 안심하세요. 저희는 그럴 생각이 없답니다."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "でもご安心を。我々にそのつもりはありません。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "However, you can be at ease. We have no intention of harming you."
L18_1.m_Talk_ENG = L19_1
L19_1 = "不過請放心，我們沒那個打算。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "แต่ถึงยังไงคุณก็สบายใจได้แล้วนะคะ เราไม่มีเจตนาจะทำร้ายคุณหรอกค่ะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Tuy nhiên, cứ yên tâm. Chúng tôi không có ý định làm hại thái tử."
L18_1.m_Talk_VTN = L19_1
L19_1 = "但请放心。我们无意与你战斗。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Sie können aber beruhigt sein. Wir haben nicht die Absicht, Ihnen zu schaden."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Mais vous pouvez garder l'esprit tranquille, nous n'avons aucunement l'intention de vous nuire."
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
L20_1 = "EP9_ACT4_STAGE4_END@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 378
L19_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L20_1 = "UNIT_PRIDE"
L19_1.m_Face = L20_1
L20_1 = "EDEL_ESPR_SHADOW_NULL"
L19_1.m_CharStrID = L20_1
L19_1.m_Pos = "C"
L20_1 = "저희들은 그저…… 저희의 소망을 위해 늑대를 데려가기만 하면 되거든요."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "我々はただ……我々の願いのために狼を連れていくだけで十分なのです。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "We merely... We just need to take the Wolf to fulfill our desires."
L19_1.m_Talk_ENG = L20_1
L20_1 = "我們……只想把狼帶走，完成我們的願望而已。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "เราเพียง... เราแค่อยากเอาตัวหมาป่าไปเติมเต็มความปรารถนาของเราก็เท่านั้น"
L19_1.m_Talk_THA = L20_1
L20_1 = "Chúng tôi chỉ là... Chúng tôi chỉ cần đưa con sói đi để hoàn thành ước nguyện của mình."
L19_1.m_Talk_VTN = L20_1
L20_1 = "我们只想要填补自身的欲望……我们只需要将狼带走。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Wir müssen nur ... Alles, was wir tun müssen, ist den Wolf für unseren Wunsch zu nehmen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Tout ce qui nous intéresse... c'est de satisfaire nos désirs. Autrement dit, la louve."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "EP9_ACT4_STAGE4_END@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 378
L20_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "UNIT_SERIOUS"
L20_1.m_Face = L21_1
L21_1 = "PRINCE_KNIGHT_NULL_NULL"
L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L20_1.m_Crash = 30
L21_1 = "멈춰라! 내가 그걸 용납할 것 같으냐!!"
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "止まれ！　私がそれを許すとでも思っているのか！！"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Stop! Do you think that I will just accept your decision?!"
L20_1.m_Talk_ENG = L21_1
L21_1 = "站住！你們以為我會同意嗎！！"
L20_1.m_Talk_TWN = L21_1
L21_1 = "หยุดนะ! คิดว่าข้าจะยอมรับการตัดสินใจของเจ้าโดยดุษณีหรือไร?!"
L20_1.m_Talk_THA = L21_1
L21_1 = "Dừng lại! Các ngươi tưởng ta sẽ cứ thế chấp nhận ư?!"
L20_1.m_Talk_VTN = L21_1
L21_1 = "住手！你们以为我会同意吗！！"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Stopp! Glaubt ihr etwa, ich akzeptiere das so einfach?!"
L20_1.m_Talk_DEU = L21_1
L21_1 = "Stop ! Vous pensez peut-être que je vais accepter ça ?"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP9_ACT4_STAGE4_END@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 378
L21_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_Face = "UNIT_LAUGH"
L22_1 = "EDEL_ESPR_SHADOW_NULL"
L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "아이 참, 이제 와서 막으려고 하셔도 소용없답니다."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "まあ、今更止めようとしても無駄ですよ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Aw, don’t be ridiculous. Even if you try to stop us now, it’s pointless."
L21_1.m_Talk_ENG = L22_1
L22_1 = "哎呀，真是的，不同意又能如何呢？你也攔不住。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อ้าว อย่าพูดจาเหลวไหลสิคะ ต่อให้คุณมาพยายามหยุดเราเอาตอนนี้ก็ไม่มีประโยชน์นะ"
L21_1.m_Talk_THA = L22_1
L22_1 = "Ồ, đừng ngớ ngẩn thế chứ. Ngay cả khi có cố ngăn cản chúng tôi, vô dụng thôi."
L21_1.m_Talk_VTN = L22_1
L22_1 = "可是，就算现在你阻止的了一时，也不会起多大的作用。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Oh, machen Sie sich nicht lächerlich. Selbst wenn Sie versuchen, uns jetzt aufzuhalten, ist es sinnlos."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Allons, ne faites pas l'enfant. Même si vous essayez de nous arrêter maintenant, c'est inutile."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP9_ACT4_STAGE4_END@172#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 378
L22_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "UNIT_PRIDE"
L22_1.m_Face = L23_1
L23_1 = "EDEL_ESPR_SHADOW_NULL"
L22_1.m_CharStrID = L23_1
L22_1.m_Pos = "C"
L23_1 = "그러면…… 클리파 차원에서 뵙도록 하죠."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "それでは……クリファ次元でお会いしましょう。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Then... See you at the Qlipha Dimension."
L22_1.m_Talk_ENG = L23_1
L23_1 = "那就……在逆卡巴拉次元見囉。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "เอาไว้... เจอกันที่มิติคลิฟ่านะคะ"
L22_1.m_Talk_THA = L23_1
L23_1 = "Vậy... Hẹn gặp lại ở Không Gian Qlipha."
L22_1.m_Talk_VTN = L23_1
L23_1 = "我们迟早……会在逆卡巴拉次元再会吧？"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Also dann ... wir sehen uns in der Klippa-Dimension."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Au plaisir de vous revoir... dans la dimension Qlipha."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP9_ACT4_STAGE4_END@173#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 378
L23_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "EDEL_ESPR_SHADOW_NULL"
L23_1.m_CharStrID = L24_1
L23_1.m_Pos = "C"
L24_1 = "당신이 너무 늦지만 않는다면요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "あなたが遅れなければ、ですけど。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "That is, if you aren’t too late."
L23_1.m_Talk_ENG = L24_1
L24_1 = "希望你能趕上。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "ถ้าคุณไม่สายเกินไปละก็นะ"
L23_1.m_Talk_THA = L24_1
L24_1 = "Nếu ngài không quá muộn."
L23_1.m_Talk_VTN = L24_1
L24_1 = "希望你不要来得太迟。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Es sei denn, Sie sind zu spät dran."
L23_1.m_Talk_DEU = L24_1
L24_1 = "À condition que vous puissiez rentrer à temps, bien entendu."
L23_1.m_Talk_FRA = L24_1
