L27_1 = "EP9_ACT4_STAGE4_END@176#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 176
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 378
L26_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L27_1 = "JOOSHIYOON_FENRIR_CA_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "R"
L26_1.m_Crash = 20
L27_1 = "미나 양! 제 손을 잡아요! 공간을 베고 탈출합니다!"
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "ミナさん！　僕の手を取ってください！　空間を斬って脱出します！"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Mina! Grab my hand! We’ll cut through space and escape!"
L26_1.m_Talk_ENG = L27_1
L27_1 = "米娜！抓住我的手！我們劃開空間逃出去！"
L26_1.m_Talk_TWN = L27_1
L27_1 = "มีนา! จับมือผมไว้! เราจะตัดมิติพื้นที่แล้วหนีไปกัน!"
L26_1.m_Talk_THA = L27_1
L27_1 = "Mina! Nắm lấy tay tôi! Chúng ta sẽ cắt xuyên không gian và trốn thoát!"
L26_1.m_Talk_VTN = L27_1
L27_1 = "米娜！抓住我的手！我们斩开空间逃出去！"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Mina! Nimm meine Hand! Wir werden den Raum durchtrennen und entkommen!"
L26_1.m_Talk_DEU = L27_1
L27_1 = "Mina, prends ma main ! Je vais couper l'espace pour nous créer un passage !"
L26_1.m_Talk_FRA = L27_1
