L29_1 = "UNIT_SERIOUS"
L28_1.m_Face = L29_1
L29_1 = "SEO_YOON_ALT_CA_NULL"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L28_1.m_Crash = 15
L29_1 = "나도 같이 데려가! 미스틸테인으로 요격하겠어!"
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "私も連れてって！　ミスティルテインで迎撃する！"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Hey! Take me too! I’ll hit them with Misteltein!"
L28_1.m_Talk_ENG = L29_1
L29_1 = "也帶上我！我用米斯特汀來攔截她們！"
L28_1.m_Talk_TWN = L29_1
L29_1 = "นี่! พาฉันไปด้วยสิ! ฉันจะใช้มิสเทลทีนซัดพวกมันเอง!"
L28_1.m_Talk_THA = L29_1
L29_1 = "Này! Đưa tôi đi cùng với! Tôi sẽ đánh chúng bằng Misteltein!"
L28_1.m_Talk_VTN = L29_1
L29_1 = "喂！带上我呀！我可以用米斯特丁拦住他们！"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Hey! Nimm mich auch mit! Ich werde sie mit dem Mistelzweig schlagen!"
L28_1.m_Talk_DEU = L29_1
L29_1 = "Prenez-moi avec vous ! Ma Misteltein ne sera pas de trop, vous verrez !"
L28_1.m_Talk_FRA = L29_1
