L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 181
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 378
L31_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_LAUGH"
L32_1 = "SERAPEL_QLIPHOTH_NULL_NULL"
L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "R"
L31_1.m_Crash = 20
L32_1 = "오오, 그 창은?! 새로운 고통의 풍미가 느껴지는구나……!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "おお、その槍は！？　新しい苦しみの風味を感じる……！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Ooohh! That spear! I can already taste the new pain it will deliver...!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "喔喔，那把槍是？！感受到一股新的痛覺……！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "โอววว! หอกนั่น! ข้าสัมผัสได้ถึงความเจ็บปวดครั้งใหม่ที่มันจะมอบให้ได้เลย...!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Ooohh! Ngọn giáo đó! Tôi có thể nếm trải nỗi đau mới mà nó sẽ mang lại...!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "噢噢，那个长枪是？！我能感觉到全新的痛苦的味道……！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Ooohh! Dieser Speer! Ich kann bereits den neuen Geschmack des Schmerzes spüren ...!"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Oh, cette lance... ! Je peux déjà goûter la nouvelle douleur qu'elle va m'offrir !"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "EP9_ACT4_STAGE4_END@182#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 182
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 378
L32_1.m_CutScenStrID = "EP9_ACT4_STAGE4_END"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L33_1 = "EDEL_ESPR_SHADOW_NULL"
L32_1.m_CharStrID = L33_1
L32_1.m_Pos = "L"
L33_1 = "이런, 세라펠 님. 지금 욕망을 채우려고 드는 건 조금 곤란한데요……"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "まあまあ、セラフェル様。今欲望を満たそうとするのは少々困りますけど……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "Oh dear, Lady Serapel. We think this isn’t the right time for you to chase your desires..."
L32_1.m_Talk_ENG = L33_1
L33_1 = "真傷腦筋，塞拉費爾，現在不是滿足慾望的時候……"
L32_1.m_Talk_TWN = L33_1
L33_1 = "โอ้ตายละ ท่านหญิงเซราเพลคะ เราว่าท่านไม่เหมาะจะมาไล่ตามความปรารถนาในเวลานี้นะคะ..."
L32_1.m_Talk_THA = L33_1
L33_1 = "Ôi, quý cô Serapel. Chúng tôi nghĩ rằng đây không phải là thời điểm thích hợp để cô theo đuổi dục vọng của bản thân..."
L32_1.m_Talk_VTN = L33_1
L33_1 = "真伤脑筋，塞拉费尔，现在还不是满足你欲望的时候……"
L32_1.m_Talk_SCN = L33_1
L33_1 = "Oh je, Serapel. Wir denken, dass dies nicht der richtige Zeitpunkt für Sie ist, um Ihre Wünsche zu verfolgen ..."
L32_1.m_Talk_DEU = L33_1
L33_1 = "Ma chère Serapel, ce n'est pas vraiment le moment d'assouvir vos désirs..."
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
