L36_1 = "함내 전원 충격 대비!"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "艦内の総員、衝撃に備えて！"
L35_1.m_Talk_JPN = L36_1
L36_1 = "All hands! Brace for impact!"
L35_1.m_Talk_ENG = L36_1
L36_1 = "艦內全員坐穩囉！"
L35_1.m_Talk_TWN = L36_1
L36_1 = "ทุกคน! เตรียมรับแรงกระแทก!"
L35_1.m_Talk_THA = L36_1
L36_1 = "Tất cả mọi người! Vào vị trí sẵn sàng!"
L35_1.m_Talk_VTN = L36_1
L36_1 = "舰船内全员，准备应对冲击！"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Alle! Macht euch auf den Aufprall gefasst!"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Tenez-vous prêt tout le monde, ça va chauffer !"
